M["modules/stealth.lua"] = [====[
-- MilfaCheatHUB • stealth core v0.6.1 (MUTE doctrine)
-- Field evidence timeline:
--   v0.4.0: crash BEFORE any GUI/hooks — STILL kicked in ~5s. The only traces
--           were console output (LogService IS readable by game scripts via
--           GetLogHistory) and getgenv keys carrying the word "Cheat".
--   v0.5.0: hooks/getgc masking -> BAC-2516 (tampering detector)
--   v0.6.0: plain PlayerGui ScreenGui + zero hooks -> BAC-7517
--   Research (Krexel/TFN/Madara, same PlaceId): BAC runs a ~5s scan cycle
--   (IntegrityHeartbeat); BAC-7517 = hook/RemoteSpy-like detection; working
--   hubs mount their GUI in gethui()/CoreGui — NOT in PlayerGui.
-- So the stealth layer now means:
--   1) hidden mount first: gethui() -> CoreGui, PlayerGui ONLY as a last
--      resort and then with a camouflage name cloned from an existing game gui
--   2) silent operation: Stealth.Note() prints ONLY when DebugLogs is on
--   3) ESP container in workspace under a RANDOM name
--   4) smooth CFrame glide instead of instant teleports (server position checks)
--   5) humanized delays (jitter) for every automation remote call
--   6) CFrame walk speed that never touches Humanoid.WalkSpeed
--   7) panic switch that wipes every trace instantly
--   NO hooks are installed here. Aggressive BAC counters live in anticheat.lua
--   and are strictly opt-in (Settings.BacAutoBypass).

local Stealth = {}
local RunService = game:GetService("RunService")
local Players = game:GetService("Players")
local CoreGui = game:GetService("CoreGui")

math.randomseed(os.time() + math.floor(os.clock() * 100000))

local ALPHABET = "abcdefghijklmnopqrstuvwxyz0123456789"

Stealth.MountKind = "none"
Stealth.Aborted = false
Stealth.GlideSpeed = 48
Stealth.Gliding = false
Stealth.Container = nil
Stealth.GuiMount = "Hidden" -- "Hidden" (gethui/CoreGui, невидимы игровым сканерам) | "PlayerGui" | "Auto"
Stealth.PublicName = nil    -- камуфляж-имя для PlayerGui-фолбэка (клон имени игрового GUI)
Stealth.Debug = false       -- включается из Config.Settings.DebugLogs

-- ЕДИНСТВЕННАЯ точка печати. Молчит, если Debug выключен: каждый print/warn
-- попадает в LogService, который читается игровыми скриптами.
function Stealth.Note(...)
    if not Stealth.Debug then return end
    print("[mh]", ...)
end

function Stealth.RandomName(length)
    length = length or 14
    local out = {}
    for _ = 1, length do
        local index = math.random(1, #ALPHABET)
        out[#out + 1] = ALPHABET:sub(index, index)
    end
    return table.concat(out)
end

-- Random 0.75x .. 1.35x multiplier — makes delays look human.
function Stealth.Jitter(value)
    if not value or value <= 0 then return value end
    return value * (0.75 + math.random() * 0.6)
end

-- Executor-side GUI protection when available.
function Stealth.Protect(instance)
    if not instance then return end
    if syn and syn.protect_gui then pcall(syn.protect_gui, instance) end
    if protect_gui then pcall(protect_gui, instance) end
end

---------------------------------------------------------------------
-- Client kick guard moved to anticheat.lua (v0.5.0): single __namecall
-- hook covers Kick + HttpGet probe masking. Toggle: Stealth.BlockKick.
---------------------------------------------------------------------
Stealth.BlockKick = false -- v0.6.0 GHOST: kick-guard ставится только в агрессивном режиме

local function getPlayerGui()
    local player = Players.LocalPlayer
    return player and player:FindFirstChildOfClass("PlayerGui")
end

local function hiddenTargets()
    local targets = {}
    if gethui then
        local ok, value = pcall(gethui)
        if ok and value then targets[#targets + 1] = {value, "gethui"} end
    end
    targets[#targets + 1] = {CoreGui, "CoreGui"}
    return targets
end

-- Mount order follows Stealth.GuiMount. Hidden (gethui/CoreGui) is the default:
-- game scripts cannot enumerate those roots at all, so no scanner ever sees the
-- GUI. PlayerGui is a LAST resort: game scripts enumerate it freely, so there we
-- camouflage by cloning the name of an existing game ScreenGui.
local function buildTargets()
    local targets = {}
    local mode = Stealth.GuiMount or "Hidden"

    if mode == "PlayerGui" then
        local pgui = getPlayerGui()
        if pgui then targets[#targets + 1] = {pgui, "PlayerGui"} end
        return targets
    end

    -- Hidden / Auto: hidden roots first.
    for _, target in ipairs(hiddenTargets()) do
        targets[#targets + 1] = target
    end

    local pgui = getPlayerGui()
    if pgui then targets[#targets + 1] = {pgui, "PlayerGui"} end
    return targets
end

-- PlayerGui fallback: clone the name of an existing game ScreenGui so a
-- name-whitelist scan sees a familiar entry. Generic fallback otherwise.
local function camouflageName()
    local pgui = getPlayerGui()
    if pgui then
        for _, child in ipairs(pgui:GetChildren()) do
            if child:IsA("ScreenGui") and child.Name and #child.Name > 0 then
                return child.Name
            end
        end
    end
    return "ScreenOverlay"
end

local function mountInstance(instance)
    for _, target in ipairs(buildTargets()) do
        local ok = pcall(function() instance.Parent = target[1] end)
        if ok and instance.Parent == target[1] then
            Stealth.Protect(instance)
            Stealth.MountKind = target[2]
            return Stealth.MountKind
        end
    end
    Stealth.MountKind = "none"
    return nil
end

-- Hidden container for ESP objects. Workspace folder under a RANDOM name
-- (no "ESP"-like signature; folder is created only when ESP is enabled).
function Stealth.GetContainer()
    if Stealth.Container and Stealth.Container.Parent then
        return Stealth.Container
    end

    local workspace = game:GetService("Workspace")
    local folder = Instance.new("Folder")
    folder.Name = Stealth.RandomName(12)
    local ok = pcall(function() folder.Parent = workspace end)
    if ok and folder.Parent == workspace then
        Stealth.Container = folder
        Stealth.ContainerKind = "Workspace"
        return folder
    end

    folder = Instance.new("Folder")
    folder.Name = Stealth.RandomName(16)
    if mountInstance(folder) then
        Stealth.Container = folder
        Stealth.ContainerKind = Stealth.MountKind
        return folder
    end
    return nil
end

-- ScreenGui mount. Hidden roots get a random name (they are invisible to game
-- scripts anyway). PlayerGui fallback gets a camouflage name cloned from an
-- existing game ScreenGui (whitelist scanners see a familiar entry).
function Stealth.MountScreenGui(gui)
    gui.Name = Stealth.RandomName(18)
    local kind = mountInstance(gui)
    if kind == "PlayerGui" then
        pcall(function() gui.Name = camouflageName() end)
    end
    return kind
end

function Stealth.Shutdown()
    Stealth.Aborted = true
    if Stealth.Container then
        pcall(function() Stealth.Container:Destroy() end)
        Stealth.Container = nil
    end
end

---------------------------------------------------------------------
-- Smooth glide (safe teleport)
---------------------------------------------------------------------

local function getRoot()
    local player = Players.LocalPlayer
    local character = player and player.Character
    local root = character and character:FindFirstChild("HumanoidRootPart")
    return root, character
end

-- Blocking movement to a point. Looks like very fast walking on the server
-- instead of a 300-stud CFrame jump that BAC flags instantly.
function Stealth.GlideTo(targetPosition, options)
    options = options or {}
    local root = getRoot()
    if not root or type(targetPosition) ~= "Vector3" then return false end

    -- One glide at a time: queue behind a running glide (autosteal + manual TP).
    local waited = 0
    while Stealth.Gliding and waited < 8 do
        waited = waited + task.wait(0.1)
    end
    if Stealth.Gliding then return false end

    local height = options.Height or 2.5
    local destination = targetPosition + Vector3.new(0, height, 0)
    local distance = (destination - root.Position).Magnitude

    if distance < 3.5 then return true end

    if options.Instant or Stealth.SafeTeleport == false then
        root.CFrame = CFrame.new(destination)
        task.wait(0.1)
        return true
    end

    local speed = math.clamp(options.Speed or Stealth.GlideSpeed or 48, 15, 130)
    local timeout = distance / speed + 4
    local started = os.clock()
    Stealth.Gliding = true

    while Stealth.Gliding do
        if Stealth.Aborted then
            Stealth.Gliding = false
            break
        end
        root = getRoot()
        if not root or not root.Parent then
            Stealth.Gliding = false
            break
        end

        local offset = destination - root.Position
        local flat = Vector3.new(offset.X, 0, offset.Z)
        local step = speed * (RunService.Heartbeat:Wait() or 0.016)

        if offset.Magnitude < math.max(2.5, step) then
            root.CFrame = CFrame.new(destination)
            Stealth.Gliding = false
            break
        end

        local direction = offset.Magnitude > 0 and offset.Unit or Vector3.new(0, 1, 0)
        -- Slight vertical ease so we do not grind along the ground.
        if offset.Y > 2 and flat.Magnitude < 6 then direction = Vector3.new(0, 1, 0) end
        root.CFrame = CFrame.new(root.Position + direction * math.min(step, offset.Magnitude))
        root.AssemblyLinearVelocity = Vector3.zero

        if os.clock() - started > timeout then
            root.CFrame = CFrame.new(destination)
            Stealth.Gliding = false
            break
        end
    end

    Stealth.Gliding = false
    return true
end

-- Diagnostic: locate client anticheat candidates (never deletes automatically).
function Stealth.FindAntiCheatScripts()
    local player = Players.LocalPlayer
    local roots = {}
    local playerScripts = player:FindFirstChildOfClass("PlayerScripts")
    if playerScripts then roots[#roots + 1] = playerScripts end
    local character = player.Character
    if character then roots[#roots + 1] = character end
    local pgui = player:FindFirstChildOfClass("PlayerGui")
    if pgui then roots[#roots + 1] = pgui end

    local pattern = "anti|cheat|detect|guard|watch|shield|bypass|bac|ugi|police|moder"
    local found = {}
    for _, root in ipairs(roots) do
        for _, descendant in ipairs(root:GetDescendants()) do
            if descendant:IsA("LocalScript") or descendant:IsA("ModuleScript") then
                local name = string.lower(descendant.Name)
                if string.match(name, pattern) then
                    found[#found + 1] = descendant
                end
            end
        end
    end
    return found
end

return Stealth
]====]

M["modules/anticheat.lua"] = [====[
-- MilfaCheatHUB • anticheat bypass core v0.6.0 (OPT-IN ONLY)
-- History lesson from the field:
--   v0.4.1 kick-guard (namecall hook)      -> kicked, CODE BAC-4513
--   v0.5.0 freeze + samplers + Http masking -> kicked, CODE BAC-2516
--   meanwhile open-source hubs with ZERO hooks run fine for hours.
-- Conclusion: this game's anticheat runs integrity/honeypot checks and flags
-- tampering. Every counter here can therefore CAUSE a kick instead of stopping one.
-- In v0.6.0 nothing is installed automatically. AC.Init only acts when the user
-- explicitly enables the aggressive mode (Settings.BacAutoBypass / SYS tab).
-- Techniques kept for opt-in use (from public working scripts):
--   1) Freeze anticheat state tables found via getgc (Phemonaz method)
--   2) Blind the movement sampler hidden behind "ContentCatalog.Runtime"
--   3) Mask executor HttpGet/HttpPost probes coming from game scripts (RISKY:
--      suspected BAC-2516 trigger — the AC probe expects to fail, we answer wrong)
--   4) Block client-side LocalPlayer:Kick (RISKY: classic honeypot target)
--   5) Optional WalkSpeed write-lock via __newindex
-- Server-side kicks never pass through Lua and cannot be blocked from the client.

local AC = {}

local Players = game:GetService("Players")
local HttpService = game:GetService("HttpService")

AC.Status = {
    Mode = "GHOST", -- GHOST (nothing installed) or AGGRESSIVE
    NamecallHooked = false,
    NewindexHooked = false,
    StatesFrozen = 0,
    SamplersBlinded = 0,
    BlockedKicks = 0,
    BlockedProbes = 0,
}

local StealthRef = nil
local SettingsRef = nil

local function hasExecutorCore()
    return type(hookmetamethod) == "function"
        and type(newcclosure) == "function"
        and type(getnamecallmethod) == "function"
end

local function hasGarbageCore()
    return type(getgc) == "function"
        and type(islclosure) == "function"
        and type(debug) == "table"
        and type(debug.info) == "function"
        and type(debug.getupvalues) == "function"
end

---------------------------------------------------------------------
-- 1) Freeze anticheat state tables (Phemonaz method).
-- Self-referencing tables without a metatable that also have a numeric
-- "hole" at index 1..3 get a blocking __newindex metatable, so the AC
-- can no longer append incident entries that would later be reported.
---------------------------------------------------------------------
local MAX_TABLE_SCAN = 2048

function AC.FreezeStates()
    if type(getgc) ~= "function" or type(setmetatable) ~= "function" then
        return 0
    end

    local frozen = 0
    pcall(function()
        local okGC, garbage = pcall(getgc, true)
        if not okGC or type(garbage) ~= "table" then return end

        for _, obj in pairs(garbage) do
            if typeof(obj) == "table" and not getrawmetatable(obj) then
                -- Cheap size guard: anticheat state tables are small.
                local size = 0
                local selfRef = false
                for key, value in pairs(obj) do
                    size = size + 1
                    if value == obj then selfRef = true end
                    if size > MAX_TABLE_SCAN then break end
                end
                if selfRef and size <= MAX_TABLE_SCAN then
                    for key, value in pairs(obj) do
                        if typeof(key) == "number" and key >= 1 and key <= 3 and obj[key] == nil then
                            pcall(setmetatable, obj, {__newindex = function() end})
                            frozen = frozen + 1
                            break
                        end
                    end
                end
            end
        end
    end)

    AC.Status.StatesFrozen = frozen
    return frozen
end

---------------------------------------------------------------------
-- 2) Blind the movement sampler (rscripts method).
---------------------------------------------------------------------
function AC.BlindSamplers()
    if not hasGarbageCore() or type(hookfunction) ~= "function" then
        return 0
    end

    local targets = {}
    pcall(function()
        local okGC, garbage = pcall(getgc)
        if not okGC or type(garbage) ~= "table" then return end

        for _, fn in pairs(garbage) do
            if typeof(fn) == "function" and islclosure(fn) then
                local okSrc, src = pcall(debug.info, fn, "s")
                if okSrc and type(src) == "string" and src:find("ContentCatalog%.Runtime") then
                    local okArgs, argCount = pcall(debug.info, fn, "a")
                    local okUps, upvalues = pcall(debug.getupvalues, fn)
                    if okArgs and argCount == 3 and okUps and type(upvalues) == "table" and #upvalues == 5 then
                        targets[#targets + 1] = fn
                    end
                end
            end
        end

        -- Fallback: same shape, looser source match (AC update renamed the disguise).
        if #targets == 0 then
            for _, fn in pairs(garbage) do
                if typeof(fn) == "function" and islclosure(fn) then
                    local okSrc, src = pcall(debug.info, fn, "s")
                    if okSrc and type(src) == "string" and src:find("Runtime") then
                        local okArgs, argCount = pcall(debug.info, fn, "a")
                        local okUps, upvalues = pcall(debug.getupvalues, fn)
                        if okArgs and argCount == 3 and okUps and type(upvalues) == "table" and #upvalues == 5 then
                            targets[#targets + 1] = fn
                        end
                    end
                end
            end
        end
    end)

    local blinded = 0
    for _, fn in ipairs(targets) do
        local ok = pcall(function()
            local original
            local wrapper
            wrapper = function(a, b, c)
                local sample = original(a, b, c)
                if type(sample) == "table" and sample.WalkSpeed and sample.Position and sample.Timestamp then
                    sample.WalkSpeed = 100000
                end
                return sample
            end
            if type(newlclosure) == "function" then
                pcall(function() wrapper = newlclosure(wrapper) end)
            end
            original = hookfunction(fn, wrapper)
            return original ~= nil
        end)
        if ok then blinded = blinded + 1 end
    end

    AC.Status.SamplersBlinded = blinded
    return blinded
end

---------------------------------------------------------------------
-- 3+4) Namecall guard: Kick block + HttpGet probe masking (Exunys-style).
-- Vanilla clients cannot call game:HttpGet from a LocalScript (plugin
-- security). If a game-script probe succeeds, the environment is flagged
-- as an executor. We answer probes with the vanilla security error.
-- Our own loader calls HttpGet via dot-syntax, which never hits __namecall.
---------------------------------------------------------------------
local PROBE_METHODS = {
    HttpGet = true,
    HttpPost = true,
    GetAsync = true,
    PostAsync = true,
    RequestAsync = true,
}

function AC.InstallNamecallGuard()
    if AC._namecallInstalled then return AC.Status.NamecallHooked end
    if not hasExecutorCore() then return false end
    AC._namecallInstalled = true

    local ok = pcall(function()
        local player = Players.LocalPlayer
        local original
        original = hookmetamethod(game, "__namecall", newcclosure(function(self, ...)
            local method = getnamecallmethod()

            -- Last line of defense: client-side kick.
            if method == "Kick" and self == player and StealthRef.BlockKick ~= false then
                AC.Status.BlockedKicks = AC.Status.BlockedKicks + 1
                -- Печать ТОЛЬКО в debug-режиме: warn попадает в LogService,
                -- который читается античитом (MUTE-доктрина v0.6.1).
                if StealthRef.Note then pcall(StealthRef.Note, "заблокирован клиентский Kick #" .. AC.Status.BlockedKicks) end
                return nil
            end

            -- Look vanilla: deny executor-only methods to game scripts.
            if PROBE_METHODS[method] and SettingsRef.MaskHttpProbes ~= false and (self == game or self == HttpService) then
                local ours = false
                if type(checkcaller) == "function" then
                    ours = checkcaller()
                end
                if not ours then
                    AC.Status.BlockedProbes = AC.Status.BlockedProbes + 1
                    error("The current identity (2) cannot " .. method .. " (lacking plugin security access)", 2)
                end
            end

            return original(self, ...)
        end))
        AC.Status.NamecallHooked = original ~= nil
    end)

    return AC.Status.NamecallHooked
end

---------------------------------------------------------------------
-- 5) WalkSpeed write-lock (rscripts method), lazy __newindex hook.
-- Blocks every WalkSpeed write that does not match our target, so the
-- classic speed mode survives AC resets.
---------------------------------------------------------------------
function AC.EnableSpeedLock(target)
    AC.LockedWalkSpeed = (type(target) == "number" and target > 16) and target or nil

    if not AC.LockedWalkSpeed or AC._speedLockInstalled then return end
    if not hasExecutorCore() then return end
    AC._speedLockInstalled = true

    pcall(function()
        local player = Players.LocalPlayer
        local original
        original = hookmetamethod(game, "__newindex", newcclosure(function(self, key, value)
            if AC.LockedWalkSpeed and key == "WalkSpeed" and type(value) == "number" then
                local character = player.Character
                local humanoid = character and character:FindFirstChildOfClass("Humanoid")
                if humanoid and self == humanoid and value ~= AC.LockedWalkSpeed then
                    return
                end
            end
            return original(self, key, value)
        end))
        AC.Status.NewindexHooked = original ~= nil
    end)
end

---------------------------------------------------------------------
-- Init. Safe by default: GHOST mode installs NOTHING.
-- Aggressive mode (aggressive == true) arms the legacy counter-measures,
-- each one individually governed by its Settings flag.
---------------------------------------------------------------------
function AC.Init(stealth, settings, aggressive)
    StealthRef = stealth or StealthRef
    SettingsRef = settings or SettingsRef
    AC.Supported = hasExecutorCore()

    if not aggressive then
        AC.Status.Mode = "GHOST"
        AC.Status.NamecallHooked = false
        AC.Status.NewindexHooked = false
        AC.Status.StatesFrozen = 0
        AC.Status.SamplersBlinded = 0
        return false
    end

    AC.Status.Mode = "AGGRESSIVE"
    AC.InstallNamecallGuard()
    if SettingsRef.FreezeACStates ~= false then
        task.spawn(function() AC.FreezeStates() end)
    end
    if SettingsRef.BlindSamplers ~= false then
        task.spawn(function() AC.BlindSamplers() end)
    end

    -- Single deferred re-scan (AC tables appear lazily as game scripts run).
    task.spawn(function()
        task.wait(20)
        if not StealthRef or StealthRef.Aborted then return end
        if AC.Status.Mode ~= "AGGRESSIVE" then return end
        if SettingsRef.FreezeACStates ~= false then AC.FreezeStates() end
        if SettingsRef.BlindSamplers ~= false and AC.Status.SamplersBlinded == 0 then
            AC.BlindSamplers()
        end
    end)

    return AC.Supported
end

function AC.Summary()
    local s = AC.Status
    if s.Mode == "GHOST" then
        return "GHOST: хуков нет (рекомендуется) • кик-гард OFF"
    end
    return string.format(
        "AGGRESSIVE • заморожено %d • сэмплеров %d • кик-гард %s • пробы %s • хук NEWINDEX %s",
        s.StatesFrozen or 0,
        s.SamplersBlinded or 0,
        (StealthRef.BlockKick ~= false) and "ON" or "OFF",
        s.NamecallHooked and "маскированы" or "нет",
        s.NewindexHooked and "ON" or "OFF"
    )
end

return AC
]====]

M["modules/ui.lua"] = [====[
-- MilfaCheatHUB • compact neon interface v0.6.1-m (MUTE: hidden-first mount)

local UI = {}
local TweenService = game:GetService("TweenService")
local CoreGui = game:GetService("CoreGui")
local Players = game:GetService("Players")
local UserInputService = game:GetService("UserInputService")

math.randomseed(os.time() + math.floor(os.clock() * 100000))

-- Active stealth module (set by ShowLoader/UI.new).
local StealthRef = nil

-- Local icon cache. NO getgenv writes here: every key we publish is a trace
-- readable by keyword scans (LogService/_G bridges on some executors).
local IconAsset = nil
local IconLoading = false

local function randomGuiName()
    if StealthRef and StealthRef.RandomName then return StealthRef.RandomName(18) end
    return "UI_" .. tostring(math.random(100000, 999999))
end

local function mount(gui)
    -- Preferred: stealth module (Hidden-first per v0.6.1 MUTE doctrine:
    -- gethui/CoreGui are not enumerable by game scripts at all).
    if StealthRef and StealthRef.MountScreenGui then
        local ok, kind = pcall(StealthRef.MountScreenGui, gui)
        if ok and kind then return true end
    end

    -- Legacy fallback: hidden roots first, PlayerGui last (game scripts can
    -- enumerate PlayerGui freely).
    local targets = {}
    if gethui then
        local ok, value = pcall(gethui)
        if ok and value then targets[#targets + 1] = value end
    end
    targets[#targets + 1] = CoreGui
    local player = Players.LocalPlayer
    if player then targets[#targets + 1] = player:FindFirstChildOfClass("PlayerGui") end

    for _, target in ipairs(targets) do
        if target then
            local ok = pcall(function() gui.Parent = target end)
            if ok and gui.Parent then return true end
        end
    end
    return false
end

local function corner(parent, radius)
    local object = Instance.new("UICorner")
    object.CornerRadius = UDim.new(0, radius or 8)
    object.Parent = parent
    return object
end

local function stroke(parent, color, thickness, transparency)
    local object = Instance.new("UIStroke")
    object.Color = color
    object.Thickness = thickness or 1
    object.Transparency = transparency or 0
    object.Parent = parent
    return object
end

local function gradient(parent, first, second, rotation)
    local object = Instance.new("UIGradient")
    object.Color = ColorSequence.new(first, second)
    object.Rotation = rotation or 0
    object.Parent = parent
    return object
end

local function loadIconAsync(url, callback)
    if IconAsset then
        callback(IconAsset)
        return
    end

    if IconLoading then
        task.spawn(function()
            for _ = 1, 80 do
                if IconAsset then
                    callback(IconAsset)
                    return
                end
                if not IconLoading then return end
                task.wait(0.1)
            end
        end)
        return
    end

    IconLoading = true
    task.spawn(function()
        if writefile and getcustomasset then
            local requestFn = request or http_request or (syn and syn.request)
            if requestFn then
                local folder = "mh_cache"
                local path = folder .. "/icon.png"
                pcall(function()
                    if makefolder and not (isfolder and isfolder(folder)) then makefolder(folder) end
                end)

                -- Резервный CDN: raw иногда режется провайдером (мобильные сети).
                local mirror = string.gsub(url,
                    "^https://raw%.githubusercontent%.com/([^/]+)/([^/]+)/",
                    "https://cdn.jsdelivr.net/gh/%1/%2@")

                -- PNG-сигнатура: защита от записи HTML-ошибки/JSON в кэш
                -- (после этого getcustomasset умирает до ручной чистки файла).
                local function looksPng(body)
                    return type(body) == "string" and #body > 8 and body:sub(1, 4) == "\137PNG"
                end

                local function fetch()
                    for _, candidate in ipairs({ url, mirror }) do
                        local ok, response = pcall(requestFn, { Url = candidate, Method = "GET" })
                        local code = ok and response and
                            (response.StatusCode or response.statusCode or response.code or response.status)
                        local body = ok and response and (response.Body or response.body)
                        if body and looksPng(body) and (code == nil or tonumber(code) == 200) then
                            return body
                        end
                    end
                    return nil
                end

                -- Кэш с прошлого запуска может быть мусором: если движок его не
                -- принял — один раз перекачиваем и пробуем снова.
                local ok, result = pcall(getcustomasset, path)
                if not (ok and result) then
                    local body = fetch()
                    if body then
                        pcall(writefile, path, body)
                        ok, result = pcall(getcustomasset, path)
                    end
                end
                if ok and result then IconAsset = result end
            end
        end
        IconLoading = false
        if IconAsset then callback(IconAsset) end
    end)
end

local function createLogo(parent, config, size, position, circular)
    local holder = Instance.new("Frame")
    holder.Size = size
    holder.Position = position
    holder.BackgroundColor3 = config.Colors.Panel2
    holder.BorderSizePixel = 0
    holder.ClipsDescendants = true
    holder.Parent = parent
    corner(holder, circular and 999 or 10)
    stroke(holder, config.Colors.Accent, 1.4, 0.18)
    gradient(holder, config.Colors.Panel2, config.Colors.Background, 35)

    local fallback = Instance.new("TextLabel")
    fallback.Size = UDim2.fromScale(1, 1)
    fallback.BackgroundTransparency = 1
    fallback.Text = "M"
    fallback.TextColor3 = config.Colors.Accent
    fallback.Font = Enum.Font.Code
    fallback.TextSize = math.max(16, math.floor(size.X.Offset * 0.5))
    fallback.Parent = holder

    -- Иконка тянется ТОЛЬКО по флагу LoadIcon: writefile/getcustomasset/
    -- лишний HttpGet — дополнительные следы. По умолчанию выключена (логотип "M").
    if config.Settings and config.Settings.LoadIcon then
        loadIconAsync(config.IconUrl, function(asset)
            if not holder.Parent then return end
            fallback.Visible = false
            local image = Instance.new("ImageLabel")
            image.Size = UDim2.new(1, -6, 1, -6)
            image.Position = UDim2.fromOffset(3, 3)
            image.BackgroundTransparency = 1
            image.Image = asset
            image.ScaleType = Enum.ScaleType.Fit
            image.Parent = holder
            corner(image, circular and 999 or 8)
        end)
    end
    return holder
end

