    -----------------------------------------------------------------
    -- Квадратная плавающая кнопка быстрых действий (телефон+ПК).
    -- Одна кнопка на экране; тап открывает панель действий.
    -- Перетаскивается пальцем; панель следует за кнопкой.
    -----------------------------------------------------------------
    function self:AddQuickMenu(actions)
        local quick = Instance.new("Frame")
        quick.Name = randomGuiName()
        quick.Size = UDim2.fromOffset(54, 54)
        quick.Position = UDim2.new(1, -70, 0.5, -27)
        quick.BackgroundColor3 = colors.Background
        quick.BackgroundTransparency = 0.08
        quick.BorderSizePixel = 0
        quick.Active = true
        quick.Parent = gui
        corner(quick, 12)
        stroke(quick, colors.Accent, 1.6, 0.1)
        gradient(quick, colors.Panel2, colors.Background, 90)

        local icon = Instance.new("TextLabel")
        icon.Size = UDim2.new(1, 0, 1, 0)
        icon.BackgroundTransparency = 1
        icon.Text = "М"
        icon.TextColor3 = colors.Accent
        icon.Font = Enum.Font.GothamBold
        icon.TextSize = 22
        icon.Parent = quick

        -- Тот же icon.png из корня репо (тянется один раз на все логотипы).
        if config.Settings and config.Settings.LoadIcon and config.IconUrl then
            loadIconAsync(config.IconUrl, function(asset)
                if not quick.Parent then return end
                icon.Visible = false
                local image = Instance.new("ImageLabel")
                image.Size = UDim2.new(1, -10, 1, -10)
                image.Position = UDim2.fromOffset(5, 5)
                image.BackgroundTransparency = 1
                image.Image = asset
                image.ScaleType = Enum.ScaleType.Fit
                image.Parent = quick
                corner(image, 9)
            end)
        end

        -- панель действий
        local panel = Instance.new("Frame")
        panel.Name = randomGuiName()
        panel.Size = UDim2.fromOffset(128, 8 + math.max(1, #actions) * 42)
        panel.Position = UDim2.new(1, -70, 0.5, -27 - (8 + math.max(1, #actions) * 42) - 8)
        panel.BackgroundColor3 = colors.Background
        panel.BackgroundTransparency = 0.06
        panel.BorderSizePixel = 0
        panel.Visible = false
        panel.Active = true
        panel.Parent = gui
        corner(panel, 12)
        stroke(panel, colors.Border, 1.2, 0.12)

        local panelList = Instance.new("UIListLayout")
        panelList.Padding = UDim.new(0, 6)
        panelList.HorizontalAlignment = Enum.HorizontalAlignment.Center
        panelList.VerticalAlignment = Enum.VerticalAlignment.Center
        panelList.SortOrder = Enum.SortOrder.LayoutOrder
        panelList.Parent = panel

        local open = false
        local function place()
            panel.Position = UDim2.new(
                quick.Position.X.Scale, quick.Position.X.Offset,
                quick.Position.Y.Scale, quick.Position.Y.Offset - panel.Size.Y.Offset - 8)
        end

        for index, action in ipairs(actions or {}) do
            local item = Instance.new("TextButton")
            item.Name = randomGuiName()
            item.LayoutOrder = index
            item.Size = UDim2.fromOffset(114, 36)
            item.BackgroundColor3 = colors.Panel
            item.BackgroundTransparency = 0.1
            item.BorderSizePixel = 0
            item.Text = tostring(action.Text or "?")
            item.TextColor3 = action.Color or colors.Text
            item.Font = Enum.Font.Code
            item.TextSize = 12
            item.Parent = panel
            corner(item, 9)
            stroke(item, action.Color or colors.Border, 1, 0.2)
            item.MouseButton1Click:Connect(function()
                task.spawn(function()
                    if action.Callback then action.Callback() end
                end)
            end)
        end

        -- перетаскивание квадратной кнопки (мышь + палец)
        local dragging = false
        local dragMoved = false
        local dragStart, startPos
        quick.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                dragging = true
                dragMoved = false
                dragStart = input.Position
                startPos = quick.Position
                input.Changed:Connect(function()
                    if input.UserInputState == Enum.UserInputState.End then
                        dragging = false
                        if not dragMoved then
                            open = not open
                            panel.Visible = open
                            if open then place() end
                        end
                    end
                end)
            end
        end)
        quick.InputChanged:Connect(function(input)
            if not dragging then return end
            if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
                local delta = input.Position - dragStart
                if math.abs(delta.X) + math.abs(delta.Y) > 6 then dragMoved = true end
                if dragMoved then
                    quick.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
                    if open then place() end
                end
            end
        end)

        return {
            Frame = quick,
            Panel = panel,
            SetVisible = function(_, value)
                quick.Visible = value == true
                if not value then panel.Visible = false; open = false end
            end,
            Destroy = function()
                pcall(function() panel:Destroy() end)
                pcall(function() quick:Destroy() end)
            end,
        }
    end

    -----------------------------------------------------------------
    -- Плавающий HUD: таймер раунда + строка ролей (перетаскивается).
    -----------------------------------------------------------------
    function self:AddFloatingHud()
        local hud = Instance.new("Frame")
        hud.Name = randomGuiName()
        hud.Size = UDim2.fromOffset(158, 54)
        hud.Position = UDim2.new(0.5, -79, 0, 10)
        hud.BackgroundColor3 = colors.Background
        hud.BackgroundTransparency = 0.25
        hud.BorderSizePixel = 0
        hud.Active = true
        hud.Draggable = true
        hud.Parent = gui
        corner(hud, 10)
        stroke(hud, colors.Border, 1, 0.3)

        local line1 = Instance.new("TextLabel")
        line1.Size = UDim2.new(1, -10, 0, 26)
        line1.Position = UDim2.fromOffset(5, 2)
        line1.BackgroundTransparency = 1
        line1.Text = "—:—"
        line1.TextColor3 = colors.Movement
        line1.Font = Enum.Font.Code
        line1.TextSize = 17
        line1.Parent = hud

        local line2 = Instance.new("TextLabel")
        line2.Size = UDim2.new(1, -10, 0, 18)
        line2.Position = UDim2.fromOffset(5, 30)
        line2.BackgroundTransparency = 1
        line2.Text = "роль: ?"
        line2.TextColor3 = colors.Muted
        line2.Font = Enum.Font.Code
        line2.TextSize = 9
        line2.Parent = hud

        return {
            Frame = hud,
            SetTime = function(_, value) line1.Text = tostring(value) end,
            SetInfo = function(_, value) line2.Text = tostring(value) end,
            SetVisible = function(_, value) hud.Visible = value == true end,
        }
    end

    return self
end

function UI:Destroy()
    for _, connection in ipairs(self.Connections or {}) do
        pcall(function() connection:Disconnect() end)
    end
    if self.Gui then self.Gui:Destroy() end
end

return UI
]====]

M["modules/roles.lua"] = [====[
-- MilfaCheatHUB • Murder Mystery 2
-- Role detection core v0.4.0 (FIXED against live scripts).
--
-- ПРИЧИНА КРАСНЫХ КРУГОВ v0.2.0: удалённый поиск был НЕ рекурсивным, а
-- GetPlayerData лежит НЕ в корне ReplicatedStorage (он под Remotes/Extras —
-- подтверждено рабочими скриптами R3TH/KittyHub). Из-за этого роли не
-- находились вообще -> «роль: ?», пустые алерты, мёртвые аимы и телепорты.
-- KittyHub: "MM2 moves these between updates, so resolve by recursive name
-- lookup and re-resolve if the cached instance gets reparented."
--
-- Каналы данных:
--   1) GetPlayerData (RemoteFunction, позиция в дереве НЕ важна):
--      InvokeServer() -> {[name] = {Role=..., Killed=..., Dead=...}};
--   2) пуш Remotes.Gameplay.PlayerDataChanged (RemoteEvent): сервер шлёт либо
--      ЦЕЛИКОМ таблицу, либо ОДНУ запись (name, entry) — обрабатываем оба
--      варианта (KittyHub);
--   3) фолбэк по тулзам: нож = маньяк, пистолет = шериф (мирный с пистолетом
--      = герой); чужой рюкзак не реплицируется, поэтому сканируем Character
--      (вынутое оружие) + Backpack (реплицируется только свой).
-- LocalRole защёлкивается на раунд (нож покидает руку при броске, данные
-- мигают — держим последнее известное значение).

local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Players = game:GetService("Players")

local Roles = {}

Roles.Cache = {}          -- [playerName] = "Murderer" | "Sheriff" | "Hero" | "Innocent" | "Unknown"
Roles.Alive = {}          -- [playerName] = boolean
Roles.LocalRole = nil
Roles.Debug = false
Roles.OnUpdate = nil
Roles.RemotesFound = ""   -- строка для диагностики

local dataRemote = nil
local pushEvent = nil
local connections = {}
local refreshThread = nil
local lastSearchAt = 0
local localPlayer = Players.LocalPlayer

local function note(...)
    if Roles.Debug then print("[mh roles]", ...) end
end

-- Рекурсивный резолвер с переподключением (ремоуты переезжают между апдейтами).
local function resolveRemote(name, expectClass)
    local found
    pcall(function() found = ReplicatedStorage:FindFirstChild(name, true) end)
    if found and (not expectClass or found:IsA(expectClass)) then
        return found
    end
    return nil
end

local function findRemotes(force)
    if not force and dataRemote and dataRemote.Parent and pushEvent and pushEvent.Parent then
        return
    end
    -- если что-то не найдено — полный рекурсивный обход не чаще раза в 15с
    if not force and os.clock() - lastSearchAt < 15 then return end
    lastSearchAt = os.clock()
    -- Ищем ТОЛЬКО если кэш умер (KittyHub): рекурсивный обход каждый рефреш
    -- дорого стоит на телефоне.
    local newData = resolveRemote("GetPlayerData", "RemoteFunction")
    if newData and newData ~= dataRemote then
        dataRemote = newData
    end
    local newPush = resolveRemote("PlayerDataChanged", "RemoteEvent")
    if newPush ~= pushEvent then
        pushEvent = newPush
        Roles._pushConnected = false  -- переподписаться на новый инстанс
    end
    Roles.RemotesFound = "data=" .. tostring(dataRemote ~= nil) ..
        " push=" .. tostring(pushEvent ~= nil)
    if Roles.Debug then note(Roles.RemotesFound) end
end

local function normalizeRole(value)
    if type(value) ~= "string" or value == "" then return "Unknown" end
    local lowered = string.lower(value)
    if string.find(lowered, "murder", 1, true) then return "Murderer" end
    if string.find(lowered, "sheriff", 1, true) then return "Sheriff" end
    if string.find(lowered, "hero", 1, true) then return "Hero" end
    if string.find(lowered, "inno", 1, true) then return "Innocent" end
    return "Unknown"
end

local function applyEntry(name, record)
    if type(name) ~= "string" or type(record) ~= "table" then return false end
    local role = normalizeRole(record.Role)
    -- Живость: единственное надёжное поле — Dead; поле Killed в живой игре
    -- означает «убил ли» (у маньяка становится truthy ПОСЛЕ первого убийства,
    -- и если считать его смертью — маньяк пропадает с ESP, как было в v0.3.1).
    -- Окончательную точку даёт Humanoid в Roles.IsAlive (персонаж авторитетен).
    Roles.Cache[name] = role
    Roles.Alive[name] = record.Dead ~= true
    if localPlayer and name == localPlayer.Name and role ~= "Unknown" then
        -- не даём случайному пушу сбить защёлкнутого маньяка на мирного
        if Roles.LocalRole ~= "Murderer" or role ~= "Innocent" then
            Roles.LocalRole = role
        end
    end
    return true
end

-- Политика KittyHub: заменять таблицу ТОЛЬКО если пуш реально несёт роли;
-- частичный мусор без ролей игнорируем (иначе wiping таблицы = «мы ничего не знаем»).
local function applyTable(payload)
    if type(payload) ~= "table" then return end
    local roleCount = 0
    for _, record in pairs(payload) do
        if type(record) == "table" and type(record.Role) == "string" and record.Role ~= "" then
            roleCount = roleCount + 1
        end
    end
    if roleCount == 0 then return end
    local seen = {}
    for name, record in pairs(payload) do
        if type(name) == "string" and type(record) == "table" then
            applyEntry(name, record)
            seen[name] = true
        end
    end
    -- игроки, пропавшие из таблицы: новый раунд или выход
    for name in pairs(Roles.Cache) do
        if not seen[name] then
            Roles.Cache[name] = nil
            Roles.Alive[name] = nil
            if localPlayer and name == localPlayer.Name then
                Roles.LocalRole = nil
            end
        end
    end
    if Roles.OnUpdate then pcall(Roles.OnUpdate, Roles.Cache) end
end

-- TOOL-фолбэк: вынутый нож/пистолет в Character виден всем; свой рюкзак тоже
-- реплицируется. Мирный с пистолетом = герой.
local function detectFromTools()
    for _, player in ipairs(Players:GetPlayers()) do
        local held = nil
        pcall(function()
            local character = player.Character
            local backpack = player:FindFirstChildOfClass("Backpack")
            local function has(container, toolName)
                return container and container:FindFirstChild(toolName) ~= nil
            end
            if has(character, "Knife") or (player == localPlayer and has(backpack, "Knife")) then
                held = "Murderer"
            elseif has(character, "Gun") or (player == localPlayer and has(backpack, "Gun")) then
                held = (player == localPlayer and Roles.LocalRole == "Innocent") and "Hero" or "Sheriff"
            end
        end)
        if held and held ~= Roles.Cache[player.Name] then
            Roles.Cache[player.Name] = held
            Roles.Alive[player.Name] = true
            if player == localPlayer then
                if held == "Hero" or Roles.LocalRole == nil then Roles.LocalRole = held end
            end
            note("tools: " .. player.Name .. " = " .. held)
        end
    end
end

function Roles.Refresh()
    -- findRemotes(false): перепоиск ТОЛЬКО если кэш умер (рекурсивный обход
    -- ReplicatedStorage каждый тик — дорого для телефона)
    findRemotes(false)
    Roles.Listen()

    if dataRemote then
        local ok, payload = pcall(function() return dataRemote:InvokeServer() end)
        if ok and type(payload) == "table" then
            applyTable(payload)
        else
            note("pull failed: " .. tostring(payload))
        end
    end
    detectFromTools()
    if Roles.OnUpdate then pcall(Roles.OnUpdate, Roles.Cache) end
end

function Roles.Get(playerName)
    return Roles.Cache[playerName or ""]
end

function Roles.IsAlive(playerName)
    local name = playerName or ""
    -- Персонаж авторитетен и реплицируется всем: если Humanoid жив — жив.
    local player = Players:FindFirstChild(name)
    local character = player and player.Character
    if character then
        local humanoid = character:FindFirstChildOfClass("Humanoid")
        if humanoid then return humanoid.Health > 0 end
    end
    local value = Roles.Alive[name]
    if value == nil then return true end
    return value and true or false
end

function Roles.ColorFor(role)
    local colors = {
        Murderer = Color3.fromRGB(255, 64, 64),
        Sheriff = Color3.fromRGB(64, 156, 255),
        Hero = Color3.fromRGB(255, 196, 47),
        Innocent = Color3.fromRGB(82, 255, 143),
    }
    return colors[role] or Color3.fromRGB(160, 160, 170)
end

function Roles.Label(role)
    local labels = {
        Murderer = "МАНЬЯК",
        Sheriff = "ШЕРИФ",
        Hero = "ГЕРОЙ",
        Innocent = "мирный",
        Unknown = "???",
    }
    return labels[role] or tostring(role)
end

function Roles.CountAliveByRole(role)
    local count = 0
    for name, cached in pairs(Roles.Cache) do
        if cached == role and Roles.IsAlive(name) then count = count + 1 end
    end
    return count
end

function Roles.FindByRole(role)
    local list = {}
    for name, cached in pairs(Roles.Cache) do
        if cached == role and Roles.IsAlive(name) then list[#list + 1] = name end
    end
    return list
end

function Roles.LocalIsMurderer()
    return Roles.LocalRole == "Murderer"
end

function Roles.LocalIsSheriff()
    return Roles.LocalRole == "Sheriff" or Roles.LocalRole == "Hero"
end

function Roles.Listen()
    if pushEvent and not Roles._pushConnected then
        Roles._pushConnected = true
        -- переподписка на новый инстанс: старый коннект гасим (ремоуты переезжают)
        if Roles._pushConnection then
            pcall(function() Roles._pushConnection:Disconnect() end)
            Roles._pushConnection = nil
        end
        local connection = pushEvent.OnClientEvent:Connect(function(first, second)
            if type(first) == "table" then
                applyTable(first)               -- форма 1: вся таблица
            elseif second ~= nil then
                -- форма 2: (имя ИЛИ Player-инстанс, запись) — KittyHub приводит
                -- Player к имени, иначе запись молча терялась
                local name = first
                if typeof(first) == "Instance" and first:IsA("Player") then
                    name = first.Name
                end
                if applyEntry(name, second) and Roles.OnUpdate then
                    pcall(Roles.OnUpdate, Roles.Cache)
                end
            end
        end)
        Roles._pushConnection = connection
        connections[#connections + 1] = connection
    end
end

-- Сброс на новом раунде (KittyHub clearRoles): протухшие роли прошлого
-- раунда хуже, чем их отсутствие. Триггеры: карта добавлена/удалена (ребёнок
-- workspace с CoinContainer, не Lobby) и собственный респавн.
function Roles.ResetRound()
    Roles.Cache = {}
    Roles.Alive = {}
    Roles.LocalRole = nil
    if Roles.OnUpdate then pcall(Roles.OnUpdate, Roles.Cache) end
    note("round reset")
end

function Roles.Start()
    if refreshThread then return end
    Roles._running = true  -- после Shutdown() цикл обязан стартовать заново
    refreshThread = task.spawn(function()
        while Roles._running ~= false do
            pcall(Roles.Refresh)
            task.wait(2.5)
        end
    end)
    if not Roles._roundBound then
        Roles._roundBound = true
        connections[#connections + 1] = workspace.ChildAdded:Connect(function(child)
            if child.Name ~= "Lobby" and child:IsA("Model") and child:FindFirstChild("CoinContainer") then
                Roles.ResetRound()
            end
        end)
        connections[#connections + 1] = workspace.ChildRemoved:Connect(function(child)
            -- FindFirstChild работает и на уже удалённом инстансе
            if child.Name ~= "Lobby" and child:IsA("Model") and child:FindFirstChild("CoinContainer") then
                Roles.ResetRound()
            end
        end)
        connections[#connections + 1] = localPlayer.CharacterAdded:Connect(function()
            Roles.ResetRound()
            task.delay(1.2, function()
                if Roles._running ~= false then pcall(Roles.Refresh) end
            end)
        end)
    end
end

function Roles.Shutdown()
    Roles._running = false
    for _, connection in ipairs(connections) do
        pcall(function() connection:Disconnect() end)
    end
    connections = {}
    Roles._pushConnected = false
    refreshThread = nil
end

Roles._running = true
Roles.Listen()
Roles.Start()

return Roles
]====]

M["modules/network.lua"] = [====[
-- MilfaCheatHUB • Murder Mystery 2
-- Remote registry v0.1.0 (lightweight).
--
-- MM2 networking map (verified from working hubs):
--   ReplicatedStorage.GetPlayerData                 (RemoteFunction, roles)
--   ReplicatedStorage.Remotes.Gameplay.*            (PlayerDataChanged, CoinCollected)
--   ReplicatedStorage.Remotes.Extras.GetTimer       (RemoteFunction, round timer)
--   Tool-local remotes live INSIDE the Knife/Gun tools (Stab, Events.*,
--   Gun.KnifeLocal.CreateBeam) — those are resolved at use time, not here.

local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Network = {}

function Network.new(config)
    local self = setmetatable({}, { __index = Network })
    self.Config = config
    self.Found = {}
    return self
end

function Network:GetFolder()
    local ok, folder = pcall(function()
        return ReplicatedStorage:FindFirstChild("Remotes")
    end)
    return ok and folder or nil
end

-- Resolve a dotted path like "Remotes.Gameplay.CoinCollected" from ReplicatedStorage.
function Network:Resolve(path)
    if self.Found[path] and self.Found[path].Parent then
        return self.Found[path]
    end
    local current = ReplicatedStorage
    local ok = true
    for segment in string.gmatch(path, "[^.]+") do
        local found = nil
        pcall(function() found = current:FindFirstChild(segment) end)
        if not found then
            ok = false
            break
        end
        current = found
    end
    local result = ok and current or nil
    self.Found[path] = result
    return result
end

function Network:Summary()
    local checks = {
        { "GetPlayerData", "GetPlayerData", true },
        { "PlayerDataChanged", "Remotes.Gameplay.PlayerDataChanged", false },
        { "CoinCollected", "Remotes.Gameplay.CoinCollected", false },
        { "GetTimer", "Remotes.Extras.GetTimer", true },
    }
    local lines = {}
    for _, entry in ipairs(checks) do
        local instance = self:Resolve(entry[2])
        lines[#lines + 1] = entry[1] .. ": " .. (instance and "OK" or "нет")
    end
    return "Ремоуты — " .. table.concat(lines, " • ")
end

return Network
]====]

M["modules/world.lua"] = [====[
-- MilfaCheatHUB • Murder Mystery 2
-- World/round watcher v0.3.0.
--
-- Проверено по рабочим скриптам (KittyHub/W-Azeox/R3TH):
--   * карта = Model в workspace с CoinContainer (имя НЕ "Lobby"); лобби тоже
--     имеет CoinContainer — различаем по списку карт;
--   * монеты: Model "Coin_Server" с CoinVisual.MainCoin ЛИБО голый BasePart;
--   * GunDrop — BasePart где угодно в workspace (появляется при смерти
--     шерифа), ловим DescendantAdded + рекурсивный поиск;
--   * таймер: Remotes.Extras.GetTimer (RemoteFunction, секунды) и/или
--     workspace.RoundTimerPart атрибут Time — пробуем оба канала.

local RunService = game:GetService("RunService")
local Workspace = game:GetService("Workspace")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local World = {}

World.CurrentMap = nil
World.GunDrop = nil
World.TimerRemote = nil
World.Debug = false

local connections = {}
local gunDropCallbacks = {}
local mapCallbacks = {}

local function note(...)
    if World.Debug then print("[mh world]", ...) end
end

---------------------------------------------------------------------
-- Map detection
---------------------------------------------------------------------

local function hasCoinContainer(model)
    local ok, found = pcall(function() return model:FindFirstChild("CoinContainer") end)
    return ok and found ~= nil
end

local function hasSpawns(model)
    local ok, found = pcall(function()
        return model:FindFirstChild("Spawns") or model:FindFirstChild("Spawn")
    end)
    return ok and found ~= nil
end

-- Карта раунда: НЕ лобби, содержит CoinContainer и/или Spawns.
local function looksLikeMap(model)
    if not model or not model:IsA("Model") then return false end
    if model.Name == "Lobby" then return false end
    return hasCoinContainer(model) or hasSpawns(model)
end

local function scanForMap()
    for _, child in ipairs(Workspace:GetChildren()) do
        if looksLikeMap(child) then
            return child
        end
    end
    return nil
end

function World.GetMap()
    if World.CurrentMap and World.CurrentMap.Parent then
        return World.CurrentMap
    end
    local found = scanForMap()
    if found then
        World.CurrentMap = found
        note("map found: " .. found.Name)
        for _, callback in ipairs(mapCallbacks) do pcall(callback, found) end
    end
    return found
end

function World.GetLobby()
    local ok, lobby = pcall(function() return Workspace:FindFirstChild("Lobby") end)
    return ok and lobby or nil
end

function World.IsInRound()
    return World.GetMap() ~= nil
end

-- Таймер в два канала: сначала родной ремоут, затем атрибут RoundTimerPart.
function World.GetTimer()
    if not World.TimerRemote or not World.TimerRemote.Parent then
        pcall(function()
            World.TimerRemote = ReplicatedStorage:FindFirstChild("GetTimer", true)
        end)
    end
    if World.TimerRemote then
        local ok, seconds = pcall(function() return World.TimerRemote:InvokeServer() end)
        if ok and type(seconds) == "number" then return seconds end
    end
    -- Fallback: workspace.RoundTimerPart:GetAttribute("Time")
    local ok, value = pcall(function()
        local part = Workspace:FindFirstChild("RoundTimerPart")
        return part and part:GetAttribute("Time") or nil
    end)
    if ok and type(value) == "number" then return value end
    return nil
end

-- Центр карты для телепортов: bounding box модели.
function World.GetMapCenter()
    local map = World.GetMap()
    if not map then return nil end
    local ok, center = pcall(function()
        return map:GetBoundingBox().Position
    end)
    if ok and center then return center end
    return nil
end

-- Позиция спавна в лобби (ресёрч: ~(14.7, 505.2, -61.3)).
function World.GetLobbyPosition()
    local lobby = World.GetLobby()
    local spawns = lobby and (lobby:FindFirstChild("Spawns") or lobby:FindFirstChild("Spawn"))
    if spawns then
        local base = spawns:IsA("BasePart") and spawns or spawns:FindFirstChildWhichIsA("BasePart", true)
        if base then
            return base.Position + Vector3.new(0, 3, 0)
        end
    end
    return Vector3.new(14.72, 506.2, -61.29)
end

-- Спавн карты раунда (первый Spawn/PlayerSpawn в потомках).
function World.GetMapSpawn()
    local map = World.GetMap()
    if not map then return nil end
    local spawns = map:FindFirstChild("Spawns") or map:FindFirstChild("Spawn")
    if spawns then
        local base = spawns:IsA("BasePart") and spawns or spawns:FindFirstChildWhichIsA("BasePart", true)
        if base then return base.Position + Vector3.new(0, 3.5, 0) end
    end
    pcall(function()
        for _, descendant in ipairs(map:GetDescendants()) do
            if descendant:IsA("BasePart") and (descendant.Name == "Spawn" or descendant.Name == "PlayerSpawn") then
                spawns = descendant
                break
            end
        end
    end)
    if spawns and spawns:IsA("BasePart") then return spawns.Position + Vector3.new(0, 3.5, 0) end
    local center = World.GetMapCenter()
    if center then return center + Vector3.new(0, 6, 0) end
    return nil
end

---------------------------------------------------------------------
-- Coins
---------------------------------------------------------------------

-- Часть монеты: голый BasePart или Model(Coin_Server)/CoinVisual/MainCoin.
local function coinPart(obj)
    if obj:IsA("BasePart") then return obj end
    local ok, result = pcall(function()
        local visual = obj:FindFirstChild("CoinVisual")
        if visual then
            local main = visual:FindFirstChild("MainCoin")
            if main and main:IsA("BasePart") then return main end
        end
        return obj:FindFirstChildWhichIsA("BasePart", true)
    end)
    return ok and result or nil
end

-- Собираем монеты; includeLobby добавляет монеты лобби.
function World.FindCoins(includeLobby)
    local coins = {}
    local function harvest(container)
        if not container then return end
        for _, coin in ipairs(container:GetChildren()) do
            local lowered = string.lower(coin.Name)
            if string.find(lowered, "coin", 1, true) then
                local collected = false
                pcall(function() collected = coin:GetAttribute("Collected") == true end)
                if not collected then
                    local part = coinPart(coin)
                    if part then coins[#coins + 1] = part end
                end
            end
        end
    end

    pcall(function()
        local map = World.GetMap()
        if map then harvest(map:FindFirstChild("CoinContainer")) end
        if includeLobby then
            local lobby = World.GetLobby()
            if lobby then harvest(lobby:FindFirstChild("CoinContainer")) end
        end
    end)
    return coins
end

---------------------------------------------------------------------
-- GunDrop watcher
---------------------------------------------------------------------

function World.GetGunDrop()
    if World.GunDrop and World.GunDrop.Parent then
        return World.GunDrop
    end
    local found
    pcall(function() found = Workspace:FindFirstChild("GunDrop", true) end)
    if found then World.GunDrop = found end
    return found
end

function World.OnGunDrop(callback)
    gunDropCallbacks[#gunDropCallbacks + 1] = callback
end

function World.OnMap(callback)
    mapCallbacks[#mapCallbacks + 1] = callback
end

---------------------------------------------------------------------
-- Lifecycle
---------------------------------------------------------------------

function World.Start()
    if World._started then return end
    World._started = true

    -- GunDrop появляется где угодно: следим за потомками.
    connections[#connections + 1] = Workspace.DescendantAdded:Connect(function(descendant)
        if descendant.Name == "GunDrop" then
            World.GunDrop = descendant
            note("GunDrop spawned")
            for _, callback in ipairs(gunDropCallbacks) do pcall(callback, descendant) end
            task.spawn(function()
                while descendant and descendant.Parent do task.wait(0.5) end
                if World.GunDrop == descendant then World.GunDrop = nil end
            end)
        end
    end)

    -- Границы раунда: появление/удаление карты.
    connections[#connections + 1] = Workspace.ChildAdded:Connect(function(child)
        if looksLikeMap(child) then
            World.CurrentMap = child
            note("map added: " .. child.Name)
            for _, callback in ipairs(mapCallbacks) do pcall(callback, child) end
        end
    end)
    connections[#connections + 1] = Workspace.ChildRemoved:Connect(function(child)
        if child == World.CurrentMap then
            World.CurrentMap = nil
            note("map removed")
        end
        -- GunDrop живёт внутри карты: карта удалена — пистолет тоже мёртв
        if child == World.GunDrop or (World.GunDrop and not World.GunDrop.Parent) then
            World.GunDrop = nil
        end
    end)

    task.spawn(function()
        if not game:IsLoaded() then game.Loaded:Wait() end
        task.wait(2)
        World.GetMap()
        World.GetGunDrop()
    end)
end

function World.Destroy()
    World._started = false
    for _, connection in ipairs(connections) do
        pcall(function() connection:Disconnect() end)
    end
    connections = {}
    World.CurrentMap = nil
    World.GunDrop = nil
end

return World
]====]

M["modules/mm2esp.lua"] = [====[
-- MilfaCheatHUB • Murder Mystery 2
-- Role ESP v0.3.1 (tracers, alert beep, coin highlights).
--
-- Purely client-side visuals: Highlight (see-through-walls) + BillboardGui
-- (name, role label, distance) per player character, colored by role:
-- murderer red, sheriff blue, hero amber, innocent green.
-- Optional Beam-tracers from the local character to every drawn target.
-- GunDrop gets its own highlight + billboard; coins optionally highlighted.
-- All instances live directly on characters (no container scan risk);
-- names are random per refresh cycle (stealth doctrine).

local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local SoundService = game:GetService("SoundService")

local ESP = {}

ESP.Enabled = false
ESP.Debug = false
ESP.OnAlert = nil  -- callback(message) for GUI notifications

local ConfigRef = nil
local RolesRef = nil
local WorldRef = nil
local StealthRef = nil

local running = false
local loopThread = nil
local espConnections = {} -- PlayerAdded/Removing/Character события — мгновенный рефреш
local drawData = {}       -- [player] = {Highlight, Billboard, TextLabel, Beam, Attach0, Attach1}
local gunDropDraw = nil
local gunDropSeen = false
local lastAlertAt = 0
local coinDraws = {}      -- [coinPart] = Highlight
local beepSound = nil

local function unbindLiveRefresh()
    for index, connection in ipairs(espConnections) do
        pcall(function() connection:Disconnect() end)
        espConnections[index] = nil
    end
    espConnections = {}
end

local function note(...)
    if ESP.Debug then print("[mh esp]", ...) end
end

local function beep()
    pcall(function()
        if not beepSound then
            beepSound = Instance.new("Sound")
            beepSound.SoundId = "rbxasset://sounds/electronicpingshort.wav"
            beepSound.Volume = 0.6
            beepSound.Parent = SoundService
        end
        beepSound:Play()
    end)
end

local function cleanupDraw(data)
    if not data then return end
    -- NOTE: ipairs over {Highlight, Billboard} would stop at the first nil,
    -- leaking the other instance — check each explicitly.
    if data.Highlight then pcall(function() data.Highlight:Destroy() end) end
    if data.Billboard then pcall(function() data.Billboard:Destroy() end) end
    if data.Beam then pcall(function() data.Beam:Destroy() end) end
    if data.Attach0 then pcall(function() data.Attach0:Destroy() end) end
    if data.Attach1 then pcall(function() data.Attach1:Destroy() end) end
end

-- Только трейсер (подсветка/билборд остаются) — иначе при выключении трейсеров
-- ESP на секунду мигает целиком.
local function cleanupBeam(data)
    if not data then return end
    if data.Beam then pcall(function() data.Beam:Destroy() end) data.Beam = nil end
    if data.Attach0 then pcall(function() data.Attach0:Destroy() end) data.Attach0 = nil end
    if data.Attach1 then pcall(function() data.Attach1:Destroy() end) data.Attach1 = nil end
end

local function clearAll()
    for player, data in pairs(drawData) do
        cleanupDraw(data)
        drawData[player] = nil
    end
    if gunDropDraw then
        pcall(function() gunDropDraw.Highlight:Destroy() end)
        pcall(function() gunDropDraw.Billboard:Destroy() end)
        gunDropDraw = nil
    end
end

local function targetPart(character)
    return character and (character:FindFirstChild("Head") or character:FindFirstChild("HumanoidRootPart"))
end

local function distanceTo(position)
    local player = Players.LocalPlayer
    local root = player and player.Character and player.Character:FindFirstChild("HumanoidRootPart")
    if not root or not position then return 0 end
    return (root.Position - position).Magnitude
end

local function buildBillboard(character, color)
    local head = targetPart(character)
    if not head then return nil end
    local billboard = Instance.new("BillboardGui")
    billboard.Name = StealthRef and StealthRef.RandomName(12) or "rbxESP"
    billboard.Size = UDim2.new(0, 140, 0, 34)
    billboard.StudsOffset = Vector3.new(0, 2.6, 0)
    billboard.AlwaysOnTop = true
    billboard.MaxDistance = 400

    local label = Instance.new("TextLabel")
    label.Name = "Label"
    label.Size = UDim2.new(1, 0, 1, 0)
    label.BackgroundTransparency = 1
    label.Font = Enum.Font.GothamBold
    label.TextSize = 13
    label.TextStrokeTransparency = 0.35
    label.TextColor3 = color
    label.Text = ""
    label.Parent = billboard

    billboard.Parent = head
    return billboard, label
end

local function buildHighlight(character, color)
    local highlight = Instance.new("Highlight")
    highlight.Name = StealthRef and StealthRef.RandomName(10) or "rbxHL"
    highlight.FillColor = color
    highlight.OutlineColor = color
    highlight.FillTransparency = 0.55
    highlight.OutlineTransparency = 0.1
    highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
    highlight.Parent = character
    return highlight
end

local function drawPlayer(player, settings)
    local character = player.Character
    if not character or not character.Parent then return end
    local role = RolesRef.Get(player.Name) or "Unknown"
    local alive = RolesRef.IsAlive(player.Name)

    local isTarget = role == "Murderer" or role == "Sheriff" or role == "Hero"
    if settings.EspOnlyTargets and not isTarget then
        cleanupDraw(drawData[player])
        drawData[player] = nil
        return
    end
    if not alive then
        cleanupDraw(drawData[player])
        drawData[player] = nil
        return
    end

    local color = RolesRef.ColorFor(role)
    local data = drawData[player]

    if not data or not data.Highlight or not data.Highlight.Parent then
        cleanupDraw(data)
        data = { Highlight = nil, Billboard = nil, Label = nil }
        if settings.EspHighlight then
            data.Highlight = buildHighlight(character, color)
        end
        data.Billboard, data.Label = buildBillboard(character, color)
        drawData[player] = data
    else
        if data.Highlight then data.Highlight.FillColor = color; data.Highlight.OutlineColor = color end
        if data.Billboard then data.Billboard.AlwaysOnTop = true end
    end

    local rootPart = character:FindFirstChild("HumanoidRootPart")
    local dist = rootPart and distanceTo(rootPart.Position) or 0
    if dist > (settings.EspMaxDistance or 1000) then
        cleanupDraw(data)
        drawData[player] = nil
        return
    end

    if data.Label then
        local parts = { player.Name }
        if settings.EspShowRole then parts[#parts + 1] = "[" .. RolesRef.Label(role) .. "]" end
        if settings.EspShowDistance then parts[#parts + 1] = string.format("%.0fм", dist) end
        data.Label.Text = table.concat(parts, " ")
        data.Label.TextColor3 = color
    end

    -- Murderer proximity alert (throttled to one per 6 seconds).
    if role == "Murderer" and settings.MurderAlert and dist <= (settings.MurderAlertDistance or 70) then
        local now = os.clock()
        if now - lastAlertAt > 6 then
            lastAlertAt = now
            if ESP.OnAlert then pcall(ESP.OnAlert, "МАНЬЯК рядом: " .. player.Name .. " (" .. string.format("%.0f", dist) .. "м)") end
            if settings.AlertBeep then beep() end
        end
    end

    -- Beam-трейсеры к целям (клиентский визуал).
    if settings.Tracers then
        local myRoot = Players.LocalPlayer.Character and Players.LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
        if myRoot and rootPart then
            if not data.Beam or not data.Beam.Parent then
                local ok = pcall(function()
                    local attach0 = Instance.new("Attachment")
                    attach0.Parent = myRoot
                    local attach1 = Instance.new("Attachment")
                    attach1.Parent = rootPart
                    local beam = Instance.new("Beam")
                    beam.Name = StealthRef and StealthRef.RandomName(10) or "rbxTrace"
                    beam.Attachment0 = attach0
                    beam.Attachment1 = attach1
                    beam.FaceCamera = true
                    beam.Width0 = 0.12
                    beam.Width1 = 0.12
                    beam.Transparency = NumberSequence.new(0.25)
                    beam.Color = ColorSequence.new(color)
                    beam.LightEmission = 0.8
                    beam.Parent = myRoot
                    data.Attach0 = attach0
                    data.Attach1 = attach1
                    data.Beam = beam
                end)
                if not ok then return end
            elseif data.Beam then
                data.Beam.Color = ColorSequence.new(color)
            end
        end
    elseif data.Beam then
        cleanupBeam(data)
    end
end

-- Мгновенная перерисовка: игрок вышел/зашёл/умер/заспавнился.
-- (объявлена ПОСЛЕ drawPlayer, чтобы замыкания поймали локали)
local function bindLiveRefresh()
    if espConnections[1] then return end
    local PlayersService = game:GetService("Players")
    espConnections[#espConnections + 1] = PlayersService.PlayerAdded:Connect(function(player)
        task.wait(1)
        if running then pcall(drawPlayer, player, ConfigRef.Settings) end
    end)
    espConnections[#espConnections + 1] = PlayersService.PlayerRemoving:Connect(function(player)
        cleanupDraw(drawData[player])
        drawData[player] = nil
    end)
    -- респавн любого игрока -> перерисовать его (новая модель = старые билборды мертвы)
    espConnections[#espConnections + 1] = workspace.ChildAdded:Connect(function(child)
        if child:IsA("Model") then
            for _, player in ipairs(PlayersService:GetPlayers()) do
                if player.Character == child and running then
                    cleanupDraw(drawData[player])
                    drawData[player] = nil
                    task.delay(0.5, function()
                        if running and player.Parent then pcall(drawPlayer, player, ConfigRef.Settings) end
                    end)
                end
            end
        end
    end)
end

local function drawGunDrop(settings)
    if not settings.GunDropESP and not settings.GunDropAlert then return end
    local drop = WorldRef.GetGunDrop()
    if not drop then
        gunDropSeen = false
        if gunDropDraw then
            pcall(function() gunDropDraw.Highlight:Destroy() end)
            pcall(function() gunDropDraw.Billboard:Destroy() end)
            gunDropDraw = nil
        end
        return
    end

    -- First sighting this cycle -> notification (if enabled).
    if not gunDropSeen then
        gunDropSeen = true
        if settings.GunDropAlert and ESP.OnAlert then
            local dist = distanceTo(drop.Position)
            pcall(ESP.OnAlert, "ПИСТОЛЕТ ВЫПАЛ! " .. string.format("%.0fм", dist) .. " — жми TP или включи автоподбор")
        end
    end

    if settings.GunDropESP then
        if not gunDropDraw or not gunDropDraw.Highlight or not gunDropDraw.Highlight.Parent then
            local color = Color3.fromRGB(64, 156, 255)
            local highlight = Instance.new("Highlight")
            highlight.Name = StealthRef and StealthRef.RandomName(10) or "rbxGD"
            highlight.FillColor = color
            highlight.OutlineColor = color
            highlight.FillTransparency = 0.35
            highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
            highlight.Parent = drop

            local billboard = Instance.new("BillboardGui")
            billboard.Size = UDim2.new(0, 120, 0, 26)
            billboard.StudsOffset = Vector3.new(0, 2, 0)
            billboard.AlwaysOnTop = true
            local label = Instance.new("TextLabel")
            label.Size = UDim2.new(1, 0, 1, 0)
            label.BackgroundTransparency = 1
            label.Font = Enum.Font.GothamBold
            label.TextSize = 13
            label.TextStrokeTransparency = 0.35
            label.TextColor3 = color
            label.Text = "ПИСТОЛЕТ!"
            label.Parent = billboard
            billboard.Parent = drop

            gunDropDraw = { Highlight = highlight, Billboard = billboard }
        end
    end
end

local function clearCoins()
    for coin, highlight in pairs(coinDraws) do
        pcall(function() highlight:Destroy() end)
        coinDraws[coin] = nil
    end
end

local function drawCoins(settings)
    if not settings.CoinESP then
        if next(coinDraws) then clearCoins() end
        return
    end
    local coins = WorldRef.FindCoins(false)
    local alive = {}
    local limit = 60
    for index, coin in ipairs(coins) do
        if index > limit then break end
        alive[coin] = true
        if not coinDraws[coin] or not coinDraws[coin].Parent then
            pcall(function()
                local highlight = Instance.new("Highlight")
                highlight.Name = StealthRef and StealthRef.RandomName(9) or "rbxCoin"
                highlight.FillColor = Color3.fromRGB(255, 228, 92)
                highlight.OutlineColor = Color3.fromRGB(255, 228, 92)
                highlight.FillTransparency = 0.6
                highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
                highlight.Parent = coin
                coinDraws[coin] = highlight
            end)
        end
    end
    for coin in pairs(coinDraws) do
        if not alive[coin] then
            pcall(function() coinDraws[coin]:Destroy() end)
            coinDraws[coin] = nil
        end
    end
end

local function loop()
    while running do
        local ok, err = pcall(function()
            local settings = ConfigRef.Settings
            -- Роли опрашивает свой цикл roles.lua (2.5с) + пуш PlayerDataChanged.
            -- Второй InvokeServer здесь каждый тик = двойной спам на телефон.
            if settings.PlayerESP then
                for _, player in ipairs(Players:GetPlayers()) do
                    if player ~= Players.LocalPlayer then
                        drawPlayer(player, settings)
                    end
                end
                -- drop stale entries
                for player in pairs(drawData) do
                    if not player.Parent or player == Players.LocalPlayer then
                        cleanupDraw(drawData[player])
                        drawData[player] = nil
                    end
                end
            else
                clearAll()
            end
            drawGunDrop(settings)
            drawCoins(settings)
        end)
        if not ok then note("loop: " .. tostring(err)) end
        local delay = math.max(0.4, ConfigRef.Settings.RefreshSeconds or 1)
        if ConfigRef.Settings.HumanizeDelays then delay = delay * (0.9 + math.random() * 0.3) end
        task.wait(delay)
    end
end

function ESP.SetCoins(value)
    ConfigRef.Settings.CoinESP = value and true or false
    if value and not running then
        running = true
        bindLiveRefresh()
        loopThread = task.spawn(loop)
    end
    if not value then clearCoins() end
end

function ESP.SetEnabled(value)
    ConfigRef.Settings.PlayerESP = value and true or false
    ESP.Enabled = value and true or false
    if value and not running then
        running = true
        bindLiveRefresh()
        loopThread = task.spawn(loop)
    elseif not value then
        running = false
        unbindLiveRefresh()
        clearAll()
    end
end

function ESP.Configure(config, roles, world, stealth)
    ConfigRef = config
    RolesRef = roles
    WorldRef = world
    StealthRef = stealth
    ESP.Debug = config.Settings.DebugLogs == true
end

function ESP.Destroy()
    running = false
    unbindLiveRefresh()
    clearAll()
    clearCoins()
end

return ESP
]====]

M["modules/farm.lua"] = [====[
-- MilfaCheatHUB • Murder Mystery 2
-- Coin magnet + coin farm v0.1.0.
--
-- Mechanics (verified from working hubs):
--   * coins: <map>.CoinContainer children named "Coin_Server", BasePart (or
--     Model with a BasePart inside), attribute Collected marks them done;
--   * collection is a TOUCH event: firetouchinterest(hrp, coin, 0/1) counts
--     without moving; executors without firetouchinterest fall back to a tiny
--     CFrame nudge over the coin (also a touch);
--   * the server reports the bag through Remotes.Gameplay.CoinCollected
--     OnClientEvent(player, currentCoins, maxCoins); a full bag is a soft
--     limit — StopOnFull pauses, LobbyOnFull glides to the lobby.
-- Farm modes: Teleport (glide to coin), Smooth (CFrame lerp steps), Walk
-- (Humanoid:MoveTo). All delays humanized.

local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Farm = {}

Farm.Enabled = false          -- CoinFarm toggle
Farm.MagnetEnabled = false    -- CoinMagnet toggle
Farm.CoinsCollected = 0
Farm.BagCur = nil
Farm.BagMax = nil
Farm.Status = "выключено"
Farm.Debug = false

local ConfigRef = nil
local WorldRef = nil
local StealthRef = nil

local running = false
local loopThread = nil
local coinEvent = nil

local function note(...)
    if Farm.Debug then print("[mh farm]", ...) end
end

local function getRoot()
    local player = Players.LocalPlayer
    local character = player and player.Character
    if not character then return nil, nil end
    local root = character:FindFirstChild("HumanoidRootPart")
    local humanoid = character:FindFirstChildOfClass("Humanoid")
    return root, humanoid
end

local function hasFireTouch()
    return type(firetouchinterest) == "function"
end

-- Touch one coin from the client side (this is the legal replication path
-- every working hub uses).
local function touchCoin(root, coinPart)
    local ok = pcall(function()
        firetouchinterest(root, coinPart, 0)
        firetouchinterest(root, coinPart, 1)
    end)
    if ok then return true end
    -- Fallback: small dip onto the coin so the real touch fires.
    return pcall(function()
        local base = root.CFrame
        root.CFrame = CFrame.new(coinPart.Position + Vector3.new(0, 0.4, 0))
        task.wait(0.06)
        root.CFrame = base
    end)
end

local function nearestCoin(coins, root, maxDistance)
    local best, bestDist = nil, maxDistance or math.huge
    for _, coin in ipairs(coins) do
        if coin.Parent then
            local dist = (coin.Position - root.Position).Magnitude
            if dist < bestDist then
                best, bestDist = coin, dist
            end
        end
    end
    return best, bestDist
end

---------------------------------------------------------------------
-- Magnet loop: touch coins within radius, no movement.
---------------------------------------------------------------------

local function magnetTick()
    local root = getRoot()
    if not root then return end
    local coins = WorldRef.FindCoins(ConfigRef.Settings.FarmLobbyCoins)
    if #coins == 0 then return end
    local radius = ConfigRef.Settings.MagnetRadius or 24
    local touched = 0
    for _, coin in ipairs(coins) do
        if coin.Parent and (coin.Position - root.Position).Magnitude <= radius then
            if touchCoin(root, coin) then touched = touched + 1 end
            if ConfigRef.Settings.HumanizeDelays then task.wait(0.04 + math.random() * 0.05) end
            if touched >= 6 then break end -- per-tick cap, keep it calm
        end
    end
    if touched > 0 then
        Farm.CoinsCollected = Farm.CoinsCollected + touched
        Farm.Status = "магнит: " .. tostring(touched) .. " за такт"
    end
end

---------------------------------------------------------------------
-- Farm loop: travel to coins by the chosen mode.
---------------------------------------------------------------------

local function glideTo(root, humanoid, position, speed)
    local mode = ConfigRef.Settings.FarmMode or "Smooth"
    if mode == "Teleport" then
        if ConfigRef.Settings.SafeTeleport and StealthRef and StealthRef.GlideTo then
            local done = StealthRef.GlideTo(position, { Speed = speed or 60 })
            if done then task.wait(0.05) return true end
        end
        root.CFrame = CFrame.new(position + Vector3.new(0, 2.5, 0))
        task.wait(0.05)
        return true
    elseif mode == "Walk" and humanoid then
        humanoid:MoveTo(position)
        -- wait until close or timeout
        local started = os.clock()
        while (root.Position - position).Magnitude > 4 and os.clock() - started < 6 do
            if not root.Parent then return false end
            humanoid:MoveTo(position)
            task.wait(0.2)
        end
        return true
    else
        -- Smooth: frame-based lerp, reads like fast movement on the server.
        local distance = (position + Vector3.new(0, 2.5, 0) - root.Position).Magnitude
        local stepSpeed = speed or 60
        local timeout = distance / stepSpeed + 4
        local started = os.clock()
        while root.Parent do
            local target = position + Vector3.new(0, 2.5, 0)
            local offset = target - root.Position
            if offset.Magnitude < 3 then return true end
            if os.clock() - started > timeout then
                root.CFrame = CFrame.new(target)
                return true
            end
            local delta = RunService.Heartbeat:Wait() or 0.016
            local step = math.min(stepSpeed * delta, offset.Magnitude)
            root.CFrame = root.CFrame + offset.Unit * step
        end
        return false
    end
end

local function farmTick()
    local root, humanoid = getRoot()
    if not root then return end

    -- Bag full handling.
    if Farm.BagMax and Farm.BagCur and Farm.BagCur >= Farm.BagMax then
        if ConfigRef.Settings.LobbyOnFull and StealthRef and StealthRef.GlideTo then
            Farm.Status = "сумка полна — идём в лобби"
            local pos = WorldRef.GetLobbyPosition()
            StealthRef.GlideTo(pos, { Speed = ConfigRef.Settings.GlideSpeed or 48 })
            task.wait(2)
        elseif ConfigRef.Settings.StopOnFull then
            Farm.Status = "сумка полна (" .. tostring(Farm.BagCur) .. "/" .. tostring(Farm.BagMax) .. ") — пауза"
            task.wait(3)
            return
        end
    end

    local coins = WorldRef.FindCoins(ConfigRef.Settings.FarmLobbyCoins)
    if #coins == 0 then
        Farm.Status = WorldRef.GetMap() and "монет нет на карте" or "карта не найдена (лобби?)"
        return
    end

    local coin, dist = nearestCoin(coins, root, math.huge)
    if not coin then return end

    local moved = glideTo(root, humanoid, coin.Position, ConfigRef.Settings.FarmMode == "Teleport" and 70 or 55)
    if moved then
        local freshRoot = getRoot()
        if freshRoot then
            touchCoin(freshRoot, coin)
            Farm.CoinsCollected = Farm.CoinsCollected + 1
            Farm.Status = "фарм: " .. tostring(Farm.CoinsCollected) .. " (осталось " .. tostring(#coins - 1) .. ")"
        end
    end
end

---------------------------------------------------------------------
-- Loops
---------------------------------------------------------------------

local function farmLoop()
    while running do
        if Farm.Enabled then
            local ok, err = pcall(farmTick)
            if not ok then
                Farm.Status = "ошибка: " .. tostring(err)
                note("farm: " .. tostring(err))
            end
        end
        local delay = math.max(0.35, ConfigRef.Settings.FarmDelay or 0.8)
        if ConfigRef.Settings.HumanizeDelays then delay = delay * (0.85 + math.random() * 0.4) end
        task.wait(delay)
    end
end

local function magnetLoop()
    while running do
        if Farm.MagnetEnabled then
            local ok, err = pcall(magnetTick)
            if not ok then note("magnet: " .. tostring(err)) end
        end
        local delay = 0.5
        if ConfigRef.Settings.HumanizeDelays then delay = delay * (0.8 + math.random() * 0.5) end
        task.wait(delay)
    end
end

---------------------------------------------------------------------
-- Public API
---------------------------------------------------------------------

function Farm.SetFarm(value)
    Farm.Enabled = value and true or false
    ConfigRef.Settings.CoinFarm = Farm.Enabled
    Farm.RefreshLoops()
end

function Farm.SetMagnet(value)
    Farm.MagnetEnabled = value and true or false
    ConfigRef.Settings.CoinMagnet = Farm.MagnetEnabled
    Farm.RefreshLoops()
end

function Farm.RefreshLoops()
    local want = (Farm.Enabled or Farm.MagnetEnabled)
    if want and not running then
        running = true
        loopThread = task.spawn(farmLoop)
        task.spawn(magnetLoop)
    elseif not want then
        running = false
        Farm.Status = "выключено"
    end
end

function Farm.Configure(config, world, stealth)
    ConfigRef = config
    WorldRef = world
    StealthRef = stealth
    Farm.Debug = config.Settings.DebugLogs == true

    pcall(function()
        -- ремоуты переезжают между апдейтами — ищем рекурсивно
        coinEvent = ReplicatedStorage:FindFirstChild("CoinCollected", true)
        if coinEvent then
            coinEvent.OnClientEvent:Connect(function(player, current, max)
                if current ~= nil then Farm.BagCur = tonumber(current) end
                if max ~= nil then Farm.BagMax = tonumber(max) end
            end)
        end
    end)
end

function Farm.Summary()
    local bag = "-"
    if Farm.BagCur then
        bag = tostring(Farm.BagCur) .. (Farm.BagMax and ("/" .. tostring(Farm.BagMax)) or "")
    end
    return string.format("собрано %d • сумка %s • %s", Farm.CoinsCollected, bag, Farm.Status or "")
end

function Farm.Destroy()
    running = false
end

return Farm
]====]

M["modules/combat.lua"] = [====[
-- MilfaCheatHUB • Murder Mystery 2
-- Combat v0.4.0 (FIXED against live scripts: KittyHub/R3TH/StyearX/MM2 Mods).
--
-- Причины красных кругов v0.2.0 и как теперь:
--   * удар ножом: ремоуты Events.KnifeStabbed/HandleTouched НЕ наносят урон в
--     актуальной MM2. Рабочий путь (подтверждён 3 скриптами):
--     Knife.Stab:FireServer("Down") и через ~0.06с ("Up") — пара вниз/вверх;
--   * убийство на дистанции: сервер засчитывает касание ножа, поэтому все
--     рабочие ауры делают ТП-стаб: мигнуть к цели (2.5 стада за спину),
--     stab, мигнуть обратно. Сделали режим по умолчанию;
--   * выстрел шерифа: Gun.KnifeLocal.CreateBeam.RemoteFunction(1, pos, тег);
--     сервер сам проверяет попадание. Теги: "AH2" (новые), "AH" (старые);
--     фолбэк Gun.KnifeServer.ShootGun(1, 0, "AH");
--   * бросок ножа: Knife.Events.KnifeThrown:FireServer(fromCF, toCF), где
--     fromCF — ОРИЕНТИРОВАННЫЙ (CFrame.new(from, to)), иначе нож летит мимо;
--   * всё завязано на роли — починкой roles.lua они снова живые.

local Players = game:GetService("Players")
local UserInputService = game:GetService("UserInputService")

local Combat = {}

Combat.AuraEnabled = false
Combat.SheriffAutoEnabled = false
Combat.DodgeEnabled = false
Combat.LastKillName = "—"
Combat.KillCount = 0
Combat.Status = "выключено"
Combat.Debug = false
Combat.OnNotify = nil

local ConfigRef = nil
local RolesRef = nil
local StealthRef = nil

local localPlayer = Players.LocalPlayer
local auraRunning = false
local sheriffRunning = false
local dodgeRunning = false
local lastShotAt = 0
local lastThrowAt = 0
local lastDodgeAt = 0
local dodgeConnections = {}
local watchedProjectiles = {}

local SHOT_TAGS = { "AH2", "AH" }
local shotTagIndex = 1

local function note(...)
    if Combat.Debug then print("[mh combat]", ...) end
end

local function jitter(value)
    if ConfigRef and ConfigRef.Settings.HumanizeDelays then
        return value * (0.8 + math.random() * 0.5)
    end
    return value
end

local function getCharacterParts()
    local character = localPlayer.Character
    if not character then return nil, nil end
    return character, character:FindFirstChild("HumanoidRootPart")
end

-- Найти тул (в руке или рюкзаке), при необходимости экипировать.
local function findTool(character, name)
    if character and character:FindFirstChild(name) then
        return character:FindFirstChild(name)
    end
    local backpack = localPlayer:FindFirstChildOfClass("Backpack")
    local stowed = backpack and backpack:FindFirstChild(name)
    if stowed and character then
        local humanoid = character:FindFirstChildOfClass("Humanoid")
        if humanoid then pcall(function() humanoid:EquipTool(stowed) end) end
        return character:FindFirstChild(name)
    end
    return stowed
end

local function aliveTargetRoot(targetPlayer)
    local character = targetPlayer and targetPlayer.Character
    if not character then return nil end
    local humanoid = character:FindFirstChildOfClass("Humanoid")
    local root = character:FindFirstChild("HumanoidRootPart")
    if humanoid and humanoid.Health > 0 and root then
        return root
    end
    return nil
end

-- Фолбэк роли по тулу в Character (реплицируется всем): если детект ролей
-- мигнул/опоздал, а нож/пистолет у нас В РУКЕ — роль очевидна. Это снимает
-- главный симптом «половина не работает» — жёсткий гейт по протухшему роли.
local function holdingTool(name)
    local character = localPlayer.Character
    return character and character:FindFirstChild(name) ~= nil
end

local function amMurderer()
    if RolesRef.LocalIsMurderer() then return true end
    return holdingTool("Knife") == true
end

local function amSheriff()
    if RolesRef.LocalIsSheriff() then return true end
    return holdingTool("Gun") == true
end

-- Прямая видимость между корнями (исключаем обе модели).
local function hasLineOfSight(myRoot, targetRoot, targetCharacter)
    local origin = myRoot.Position
    local direction = targetRoot.Position - origin
    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    local exclude = {}
    if localPlayer.Character then exclude[#exclude + 1] = localPlayer.Character end
    if targetCharacter then exclude[#exclude + 1] = targetCharacter end
    params.FilterDescendantsInstances = exclude
    local hit = workspace:Raycast(origin, direction, params)
    return hit == nil
end

local function nearbyTargets(radius, maxCount)
    local _, myRoot = getCharacterParts()
    if not myRoot then return {} end
    local list = {}
    for _, player in ipairs(Players:GetPlayers()) do
        if player ~= localPlayer and RolesRef.IsAlive(player.Name) then
            local root = aliveTargetRoot(player)
            if root and (root.Position - myRoot.Position).Magnitude <= radius then
                list[#list + 1] = { Player = player, Root = root }
                if maxCount and #list >= maxCount then break end
            end
        end
    end
    return list
end

---------------------------------------------------------------------
-- Нож: удар (Down/Up пара) и ТП-стаб
---------------------------------------------------------------------

-- Рабочий удар: Stab("Down") + отложенный "Up" (без него тул залипает),
-- плюс страховочный комбо StyearX: KnifeStabbed + HandleTouched(корень цели)
-- — свежие хабы шлют ОБА канала, сервер засчитывает любой.
local function stabWith(knife, targetRoot)
    local ok = false
    pcall(function()
        local stab = knife:FindFirstChild("Stab")
        if stab and stab:IsA("RemoteEvent") then
            stab:FireServer("Down")
            ok = true
            task.delay(0.07, function()
                pcall(function() stab:FireServer("Up") end)
            end)
        end
        -- страховка (StyearX KnifeAura/KillAll): пара KnifeStabbed+HandleTouched
        local events = knife:FindFirstChild("Events")
        if events then
            local stabbed = events:FindFirstChild("KnifeStabbed")
            if stabbed and stabbed:IsA("RemoteEvent") then
                pcall(function() stabbed:FireServer() end)
                ok = true
                local touched = events:FindFirstChild("HandleTouched")
                if touched and touched:IsA("RemoteEvent") and targetRoot then
                    pcall(function() touched:FireServer(targetRoot) end)
                end
            end
        end
    end)
    return ok
end

-- ТП-стаб: мигнуть за спину цели, удар, вернуть то же тело обратно.
local function tpStabTarget(knife, targetRoot, targetCharacter)
    local _, myRoot = getCharacterParts()
    if not myRoot then return false end
    local origin = myRoot.CFrame
    local moved = false
    local dist = (targetRoot.Position - myRoot.Position).Magnitude
    if dist > 6 then
        myRoot.CFrame = targetRoot.CFrame * CFrame.new(0, 0, 2.5)
        moved = true
        task.wait(jitter(0.08))
    end
    local freshKnife = localPlayer.Character and localPlayer.Character:FindFirstChild("Knife") or knife
    local hit = stabWith(freshKnife, targetRoot)
    -- физический тач-фолбэк для экзекьюторов с firetouchinterest
    pcall(function()
        local handle = freshKnife and (freshKnife:FindFirstChild("Handle") or freshKnife:FindFirstChildWhichIsA("BasePart"))
        if handle and type(firetouchinterest) == "function" then
            firetouchinterest(handle, targetRoot, 0)
            firetouchinterest(handle, targetRoot, 1)
        end
    end)
    task.wait(jitter(0.1))
    if moved and myRoot.Parent then
        myRoot.CFrame = origin
    end
    return hit
end

---------------------------------------------------------------------
-- Выстрел шерифа (CreateBeam + ShootGun фолбэк, теги AH2/AH)
---------------------------------------------------------------------

local function shotRemote(gun)
    local knifeLocal = gun:FindFirstChild("KnifeLocal")
    local createBeam = knifeLocal and knifeLocal:FindFirstChild("CreateBeam")
    if createBeam then
        local rf = createBeam:FindFirstChildOfClass("RemoteFunction")
        if rf then return rf end
        if createBeam:IsA("RemoteFunction") then return createBeam end
    end
    -- фолбэк: старый путь R3TH — Gun.KnifeServer.ShootGun
    local knifeServer = gun:FindFirstChild("KnifeServer")
    local shootGun = knifeServer and knifeServer:FindFirstChild("ShootGun")
    if shootGun and shootGun:IsA("RemoteFunction") then return shootGun end
    local any = gun:FindFirstChildWhichIsA("RemoteFunction", true)
    return any
end

local function fireShot(gun, targetPosition)
    local remote = shotRemote(gun)
    if not remote then return false, "ремоут выстрела не найден" end
    local isShootGun = remote.Parent and remote.Parent.Name == "ShootGun"
    local ok = pcall(function()
        if isShootGun then
            remote:InvokeServer(1, 0, SHOT_TAGS[shotTagIndex])
        else
            remote:InvokeServer(1, targetPosition, SHOT_TAGS[shotTagIndex])
        end
    end)
    if not ok then
        -- переключаем тег: сервер принял другой формат
        shotTagIndex = (shotTagIndex % #SHOT_TAGS) + 1
        pcall(function()
            if isShootGun then
                remote:InvokeServer(1, 0, SHOT_TAGS[shotTagIndex])
            else
                remote:InvokeServer(1, targetPosition, SHOT_TAGS[shotTagIndex])
            end
        end)
    end
    return true
end

---------------------------------------------------------------------
-- SheriffAim: тихий выстрел в маньяка (кнопка/клавиша/авто-цикл)
---------------------------------------------------------------------

local function trySheriffShot()
    local settings = ConfigRef.Settings
    if not amSheriff() then
        Combat.Status = "нужна роль ШЕРИФ/ГЕРОЙ"
        return false, "нужна роль ШЕРИФ/ГЕРОЙ"
    end
    local character, myRoot = getCharacterParts()
    local gun = character and findTool(character, "Gun")
    if not gun then
        Combat.Status = "пистолет не найден"
        return false, "пистолет не найден"
    end
    if not myRoot then
        return false, "нет персонажа"
    end
    -- KittyHub: сервер отклоняет выстрел из пистолета, который ещё не в руке.
    -- Ждём экип до 0.35с (первый выстрел после подбора — типичный «не работает»).
    if gun.Parent ~= character then
        local began = os.clock()
        while gun.Parent ~= character and os.clock() - began < 0.35 do
            task.wait(0.05)
            character = localPlayer.Character
            if not character then return false, "нет персонажа" end
        end
        if gun.Parent ~= character then
            local humanoid = character and character:FindFirstChildOfClass("Humanoid")
            local backpack = localPlayer:FindFirstChildOfClass("Backpack")
            local stowed = backpack and backpack:FindFirstChild("Gun")
            if stowed and humanoid then
                pcall(function() humanoid:EquipTool(stowed) end)
                gun = character:FindFirstChild("Gun") or stowed
            end
        end
        if gun and gun.Parent ~= character then
            Combat.Status = "пистолет не экипировался"
            return false, "пистолет не экипировался"
        end
    end

    local murderers = RolesRef.FindByRole("Murderer")
    if #murderers == 0 then
        return false, "маньяк неизвестен — роли не определены"
    end
    for _, name in ipairs(murderers) do
        local target = Players:FindFirstChild(name)
        local root = target and aliveTargetRoot(target)
        if root and target and target.Character then
            local dist = (root.Position - myRoot.Position).Magnitude
            if dist <= (settings.SheriffRange or 300) then
                if not hasLineOfSight(myRoot, root, target.Character) then
                    Combat.Status = "маньяк за препятствием"
                    return false, "маньяк за препятствием"
                end
                local ok = fireShot(gun, root.Position)
                if ok then
                    Combat.LastKillName = name
                    Combat.KillCount = Combat.KillCount + 1
                    Combat.Status = "выстрел: " .. name
                    if Combat.OnNotify then pcall(Combat.OnNotify, "Выстрел в маньяка: " .. name) end
                    lastShotAt = os.clock()
                    return true, "выстрел в " .. name
                end
                return false, "ремоут выстрела не сработал"
            end
        end
    end
    return false, "маньяк вне дистанции"
end

local function sheriffLoop()
    while sheriffRunning do
        local ok, err = pcall(trySheriffShot)
        if not ok then note("sheriff: " .. tostring(err)) end
        task.wait(jitter(1.2))
    end
end

---------------------------------------------------------------------
-- Аура маньяка: ТП-стаб по ближайшим
---------------------------------------------------------------------

local function auraLoop()
    while auraRunning do
        local settings = ConfigRef.Settings
        if not amMurderer() then
            Combat.Status = "нужна роль МАНЬЯК"
        else
            local character = localPlayer.Character
            local knife = character and findTool(character, "Knife")
            if not knife then
                Combat.Status = "нож не найден"
            else
                local targets = nearbyTargets(settings.AuraRadius or 14, 2)
                if #targets == 0 then
                    Combat.Status = "целей рядом нет"
                else
                    for _, target in ipairs(targets) do
                        tpStabTarget(knife, target.Root, target.Player.Character)
                        -- честный счёт: убийство = цель реально умерла (Health),
                        -- а не «мы отправили удар»
                        task.wait(jitter(0.3))
                        if not aliveTargetRoot(target.Player) then
                            Combat.KillCount = Combat.KillCount + 1
                            Combat.LastKillName = target.Player.Name
                            Combat.Status = "убит: " .. target.Player.Name
                        else
                            Combat.Status = "удар: " .. target.Player.Name
                        end
                        task.wait(jitter(math.max(0.5, settings.AuraDelay or 1.0)))
                    end
                end
            end
        end
        task.wait(jitter(0.4))
    end
end

---------------------------------------------------------------------
-- KILL ALL: маньяк — ТП-стаб всех в радиусе; шериф — очередь выстрелов
---------------------------------------------------------------------

function Combat.KillAll()
    if not amMurderer() and not amSheriff() then
        return false, "нужна роль МАНЬЯК или ШЕРИФ"
    end
    local radius = (ConfigRef.Settings.KillAllRadius or 60)
    local targets = nearbyTargets(radius, 12)
    if #targets == 0 then
        return false, "никого в радиусе " .. tostring(radius)
    end
    local isMurderer = amMurderer()
    if isMurderer then
        local character = localPlayer.Character
        local knife = character and findTool(character, "Knife")
        if not knife then return false, "нож не найден" end
        task.spawn(function()
            for _, target in ipairs(targets) do
                local fresh = localPlayer.Character
                local freshKnife = fresh and findTool(fresh, "Knife")
                if freshKnife then
                    tpStabTarget(freshKnife, target.Root, target.Player.Character)
                    task.wait(jitter(0.3))
                    if not aliveTargetRoot(target.Player) then
                        Combat.KillCount = Combat.KillCount + 1
                        Combat.LastKillName = target.Player.Name
                    end
                end
                task.wait(jitter(0.45))
            end
            Combat.Status = "kill all: " .. tostring(#targets) .. " целей"
        end)
    else
        local character = localPlayer.Character
        local gun = character and findTool(character, "Gun")
        if not gun then return false, "пистолет не найден" end
        task.spawn(function()
            for _, target in ipairs(targets) do
                local freshChar = localPlayer.Character
                local freshGun = freshChar and findTool(freshChar, "Gun")
                if freshGun and freshGun.Parent == freshChar then
                    fireShot(freshGun, target.Root.Position)
                    task.wait(jitter(0.35))
                    if not aliveTargetRoot(target.Player) then
                        Combat.KillCount = Combat.KillCount + 1
                        Combat.LastKillName = target.Player.Name
                    end
                end
                task.wait(jitter(0.25))
            end
            Combat.Status = "kill all: " .. tostring(#targets) .. " выстрелов"
        end)
    end
    return true, "целей: " .. tostring(#targets)
end

---------------------------------------------------------------------
-- MurderAim: тихий бросок ножа в шерифа (ориентированный CFrame)
---------------------------------------------------------------------

local function throwKnifeAt(knife, fromRoot, targetPosition)
    local character = localPlayer.Character
    local hand = character and (character:FindFirstChild("RightHand") or character:FindFirstChild("Right Arm")) or fromRoot
    local from = hand.CFrame
    if (targetPosition - hand.Position).Magnitude > 0.5 then
        from = CFrame.new(hand.Position, targetPosition)
    end
    local ok = pcall(function()
        local events = knife:FindFirstChild("Events")
        local thrown = events and events:FindFirstChild("KnifeThrown")
        if thrown and thrown:IsA("RemoteEvent") then
            -- KittyHub: второй аргумент — ОРИЕНТИРОВАННЫЙ CFrame (поза from).
            -- Голый CFrame.new(point) разворачивает нож по мировой оси — он летит
            -- мимо и сервер отклоняет попадание. Именно это ломало бросок.
            thrown:FireServer(from, CFrame.new(targetPosition) * (from - from.Position))
            return
        end
        local throw = knife:FindFirstChild("Throw")
        if throw and throw:IsA("RemoteEvent") then
            throw:FireServer(from, CFrame.new(targetPosition) * (from - from.Position))
        else
            error("нет ремоута броска")
        end
    end)
    return ok
end

function Combat.MurderAimThrow()
    local settings = ConfigRef.Settings
    if not amMurderer() then
        Combat.Status = "нужна роль МАНЬЯК"
        return false, "нужна роль МАНЬЯК"
    end
    local character, myRoot = getCharacterParts()
    local knife = character and findTool(character, "Knife")
    if not knife then
        Combat.Status = "нож не найден"
        return false, "нож не найден"
    end
    if not myRoot then
        return false, "нет персонажа"
    end
    local sheriffs = RolesRef.FindByRole("Sheriff")
    if #sheriffs == 0 then
        return false, "шериф неизвестен — роли не определены"
    end
    local target = Players:FindFirstChild(sheriffs[1])
    local root = target and aliveTargetRoot(target)
    if not root or not (target and target.Character) then
        return false, "шериф недоступен"
    end
    local dist = (root.Position - myRoot.Position).Magnitude
    if dist > (settings.AimMaxDistance or 260) then
        return false, string.format("далеко: %.0fм", dist)
    end
    if os.clock() - lastThrowAt < 1.0 then
        return false, "нож ещё летит (перезарядка)"
    end
    if not hasLineOfSight(myRoot, root, target.Character) then
        Combat.Status = "шериф за препятствием"
        return false, "шериф за препятствием"
    end

    local ok = throwKnifeAt(knife, myRoot, root.Position)
    lastThrowAt = os.clock()
    if not ok then
        Combat.Status = "ремоут броска не найден"
        return false, "ремоут броска не найден"
    end
    Combat.LastKillName = sheriffs[1]
    Combat.Status = "бросок ножа: " .. sheriffs[1]
    if Combat.OnNotify then pcall(Combat.OnNotify, "Бросок ножа в шерифа: " .. sheriffs[1]) end
    return true, "бросок в " .. sheriffs[1]
end

---------------------------------------------------------------------
-- SheriffAimShot: то же, но по кнопке/клавише (без цикла)
---------------------------------------------------------------------

function Combat.SheriffAimShot()
    return trySheriffShot()
end

---------------------------------------------------------------------
-- Бросок ножа в точку прицела
---------------------------------------------------------------------

function Combat.ThrowAtAim()
    if not amMurderer() then
        return false, "нужна роль МАНЬЯК"
    end
    local character, myRoot = getCharacterParts()
    local knife = character and findTool(character, "Knife")
    if not knife then return false, "нож не найден" end
    if not myRoot then return false, "нет персонажа" end
    if os.clock() - lastThrowAt < 1.0 then
        return false, "нож ещё летит (перезарядка)"
    end
    local camera = workspace.CurrentCamera
    if not camera then return false, "нет камеры" end
    local targetPoint = nil
    pcall(function()
        local mouse = UserInputService:GetMouseLocation()
        local ray = camera:ViewportPointToRay(mouse.X, mouse.Y)
        local params = RaycastParams.new()
        params.FilterType = Enum.RaycastFilterType.Exclude
        if localPlayer.Character then params.FilterDescendantsInstances = { localPlayer.Character } end
        local result = workspace:Raycast(ray.Origin, ray.Direction * 600, params)
        targetPoint = result and result.Position or (ray.Origin + ray.Direction * 200)
    end)
    if not targetPoint then
        targetPoint = (camera.CFrame * CFrame.new(0, 0, -150)).Position
    end
    local ok = throwKnifeAt(knife, myRoot, targetPoint)
    lastThrowAt = os.clock()
    if not ok then return false, "ремоут броска не найден" end
    Combat.Status = "бросок в прицел"
    return true, "бросок выполнен"
end

---------------------------------------------------------------------
-- AutoDodge: резкий стрейф от летящих ножей и стрелков в упор
---------------------------------------------------------------------

local DODGE_NAMES = { "knife", "throw", "projectile", "bullet" }

local function isDodgeName(name)
    local lowered = string.lower(name)
    for _, fragment in ipairs(DODGE_NAMES) do
        if string.find(lowered, fragment, 1, true) then return true end
    end
    return false
end

local function trackProjectile(part)
    if watchedProjectiles[part] then return end
    watchedProjectiles[part] = os.clock() + 4
end

local function dodgeNow(myRoot, threatPosition)
    local settings = ConfigRef.Settings
    local power = settings.DodgePower or 12
    local base = threatPosition - myRoot.Position
    base = Vector3.new(base.X, 0, base.Z)
    if base.Magnitude < 0.5 then base = myRoot.CFrame.LookVector end
    base = base.Unit
    local perp = Vector3.new(-base.Z, 0, base.X)
    if math.random() < 0.5 then perp = -perp end
    local target = myRoot.Position + perp * power - base * (power * 0.2) + Vector3.new(0, 2, 0)
    myRoot.CFrame = CFrame.lookAt(target, target - base)
    lastDodgeAt = os.clock()
    Combat.Status = "dodge!"
end

local function dodgeLoop()
    while dodgeRunning do
        local _, myRoot = getCharacterParts()
        if myRoot then
            local now = os.clock()
            if now - lastDodgeAt > (ConfigRef.Settings.DodgeCooldown or 1.2) then
                local dodged = false
                for part, deadline in pairs(watchedProjectiles) do
                    if dodged then break end
                    if now > deadline or not part.Parent then
                        watchedProjectiles[part] = nil
                    else
                        local ok, threat = pcall(function()
                            local velocity = part.AssemblyLinearVelocity
                            local speed = velocity.Magnitude
                            if speed < 20 then return false end
                            local offset = myRoot.Position - part.Position
                            local dist = offset.Magnitude
                            if dist > (ConfigRef.Settings.DodgeRadius or 45) or dist < 2 then return false end
                            return velocity.Unit:Dot(offset.Unit) > 0.82
                        end)
                        if ok and threat then
                            dodgeNow(myRoot, part.Position)
                            dodged = true
                        end
                    end
                end
                if not dodged then
                    for _, player in ipairs(Players:GetPlayers()) do
                        if dodged then break end
                        if player ~= localPlayer then
                            -- угрозой считаем маньяка/шерифа по ролям ИЛИ любого
                            -- с ножом в руке (стрелявшего героя фиксируем по пистолету)
                            local role = RolesRef.Get(player.Name)
                            local character = player.Character
                            local root = character and character:FindFirstChild("HumanoidRootPart")
                            local armed = role == "Murderer" or role == "Sheriff" or role == "Hero"
                                or (character and (character:FindFirstChild("Knife") or character:FindFirstChild("Gun"))) ~= nil
                            if root and armed and RolesRef.IsAlive(player.Name) then
                                local dist = (root.Position - myRoot.Position).Magnitude
                                if dist < 16 then
                                    local look = root.CFrame.LookVector
                                    local toMe = (myRoot.Position - root.Position).Unit
                                    if look:Dot(toMe) > 0.78 then
                                        dodgeNow(myRoot, root.Position)
                                        dodged = true
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
        task.wait(0.12)
    end
end

function Combat.SetDodge(value)
    Combat.DodgeEnabled = value and true or false
    ConfigRef.Settings.AutoDodge = Combat.DodgeEnabled
    if value and not dodgeRunning then
        dodgeRunning = true
        dodgeConnections[#dodgeConnections + 1] = workspace.DescendantAdded:Connect(function(descendant)
            if dodgeRunning and descendant:IsA("BasePart") and isDodgeName(descendant.Name) then
                trackProjectile(descendant)
            end
        end)
        pcall(function()
            for _, descendant in ipairs(workspace:GetDescendants()) do
                if descendant:IsA("BasePart") and isDodgeName(descendant.Name) then
                    trackProjectile(descendant)
                end
            end
        end)
        task.spawn(dodgeLoop)
    elseif not value then
        dodgeRunning = false
        for _, connection in ipairs(dodgeConnections) do
            pcall(function() connection:Disconnect() end)
        end
        dodgeConnections = {}
        watchedProjectiles = {}
        Combat.Status = "выключено"
    end
end

---------------------------------------------------------------------
-- Public API
---------------------------------------------------------------------

function Combat.SetAura(value)
    Combat.AuraEnabled = value and true or false
    ConfigRef.Settings.KnifeAura = Combat.AuraEnabled
    if value and not auraRunning then
        auraRunning = true
        task.spawn(auraLoop)
    elseif not value then
        auraRunning = false
        Combat.Status = "выключено"
    end
end

function Combat.SetSheriffAuto(value)
    Combat.SheriffAutoEnabled = value and true or false
    ConfigRef.Settings.SheriffAuto = Combat.SheriffAutoEnabled
    if value and not sheriffRunning then
        sheriffRunning = true
        task.spawn(sheriffLoop)
    elseif not value then
        sheriffRunning = false
        Combat.Status = "выключено"
    end
end

function Combat.Configure(config, roles, stealth)
    ConfigRef = config
    RolesRef = roles
    StealthRef = stealth
    Combat.Debug = config.Settings.DebugLogs == true
end

function Combat.Destroy()
    auraRunning = false
    sheriffRunning = false
    dodgeRunning = false
    for _, connection in ipairs(dodgeConnections) do
        pcall(function() connection:Disconnect() end)
    end
    dodgeConnections = {}
    watchedProjectiles = {}
end

return Combat
]====]

M["modules/movement.lua"] = [====[
-- MilfaCheatHUB • Murder Mystery 2
-- Movement & teleports v0.1.0.
--
-- MM2 has no known movement anticheat (9 public hubs use WalkSpeed 18-50,
-- noclip via Humanoid:ChangeState(11), teleports freely). We still keep the
-- sane defaults: speed slider capped at 50, teleports through glide by
-- default (CALM doctrine), CharacterAdded re-apply.

local Players = game:GetService("Players")
local UserInputService = game:GetService("UserInputService")
local RunService = game:GetService("RunService")

local Movement = {}

Movement.AntiAFKEnabled = false
Movement.Debug = false
Movement.OnNotify = nil

local ConfigRef = nil
local StealthRef = nil

local connections = {}
local noclipRunning = false
local infJumpRunning = false
local clickTPActive = false
local antiAFKConnection = nil
local clickTPConnection = nil
local localPlayer = Players.LocalPlayer

local function note(...)
    if Movement.Debug then print("[mh move]", ...) end
end

local function getCharacterParts()
    local character = localPlayer and localPlayer.Character
    if not character then return nil, nil end
    return character:FindFirstChildOfClass("Humanoid"), character:FindFirstChild("HumanoidRootPart")
end

---------------------------------------------------------------------
-- Speed / jump
---------------------------------------------------------------------

function Movement.ApplySpeed(value)
    local humanoid = getCharacterParts()
    if humanoid and value and value > 0 then
        pcall(function() humanoid.WalkSpeed = value end)
    end
end

function Movement.ApplyJump(value)
    local humanoid = getCharacterParts()
    if humanoid and value and value > 0 then
        pcall(function()
            humanoid.UseJumpPower = true
            humanoid.JumpPower = value
        end)
    end
end

---------------------------------------------------------------------
-- Infinite jump
---------------------------------------------------------------------

local function setInfJump(value)
    infJumpRunning = value and true or false
    if value then
        task.spawn(function()
            while infJumpRunning do
                task.wait(0.05)
                if UserInputService.JumpRequest then
                    local humanoid = getCharacterParts()
                    if humanoid then pcall(function() humanoid:ChangeState(Enum.HumanoidStateType.Jumping) end) end
                end
            end
        end)
    end
end

---------------------------------------------------------------------
-- Noclip
---------------------------------------------------------------------

local function setNoclip(value)
    noclipRunning = value and true or false
    if value then
        task.spawn(function()
            while noclipRunning do
                local _, root = getCharacterParts()
                if root then
                    pcall(function()
                        for _, part in ipairs(root.Parent:GetDescendants()) do
                            if part:IsA("BasePart") and part.CanCollide then
                                part.CanCollide = false
                            end
                        end
                    end)
                end
                RunService.Heartbeat:Wait()
            end
            -- restore collisions on disable
            local _, root = getCharacterParts()
            if root and root.Parent then
                pcall(function()
                    for _, part in ipairs(root.Parent:GetDescendants()) do
                        if part:IsA("BasePart") then part.CanCollide = true end
                    end
                    root.Parent.PrimaryPart = root
                    root.CanCollide = true
                end)
            end
        end)
    end
end

---------------------------------------------------------------------
-- Click TP (glide to clicked point)
---------------------------------------------------------------------

local function setClickTP(value)
    clickTPActive = value and true or false
    if value then
        if clickTPConnection then
            pcall(function() clickTPConnection:Disconnect() end)
            clickTPConnection = nil
        end
        clickTPConnection = UserInputService.InputBegan:Connect(function(input, processed)
            if not clickTPActive or processed then return end
            if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then
                return
            end
            local camera = workspace.CurrentCamera
            if not camera then return end
            local ray = camera:ViewportPointToRay(input.Position.X, input.Position.Y)
            local params = RaycastParams.new()
            params.FilterType = Enum.RaycastFilterType.Exclude
            local character = localPlayer and localPlayer.Character
            if character then params.FilterDescendantsInstances = { character } end
            local result = workspace:Raycast(ray.Origin, ray.Direction * 1000, params)
            if result and StealthRef and StealthRef.GlideTo then
                note("clickTP -> " .. tostring(result.Position))
                task.spawn(function()
                    StealthRef.GlideTo(result.Position + Vector3.new(0, 2, 0), {})
                end)
            end
        end)
    end
end

---------------------------------------------------------------------
-- Public toggles (used by features.lua)
---------------------------------------------------------------------

function Movement.SetInfJump(value)
    if ConfigRef then ConfigRef.Settings.InfiniteJump = value and true or false end
    setInfJump(value and true or false)
end

function Movement.SetNoclip(value)
    if ConfigRef then ConfigRef.Settings.Noclip = value and true or false end
    setNoclip(value and true or false)
end

function Movement.SetClickTP(value)
    if ConfigRef then ConfigRef.Settings.ClickTP = value and true or false end
    setClickTP(value and true or false)
end

---------------------------------------------------------------------
-- Teleports
---------------------------------------------------------------------

function Movement.ToLobby()
    if StealthRef and StealthRef.GlideTo then
        task.spawn(function()
            local position = Vector3.new(14.72, 506.2, -61.29)
            local world = Movement.WorldRef
            if world and world.GetLobbyPosition then
                local found = world.GetLobbyPosition()
                if found then position = found end
            end
            StealthRef.GlideTo(position, { Speed = ConfigRef.Settings.GlideSpeed or 48 })
            if Movement.OnNotify then pcall(Movement.OnNotify, "Телепорт в лобби выполнен") end
        end)
        return true
    end
    return false
end

function Movement.ToMap()
    -- WorldRef is injected to avoid a circular dependency.
    local world = Movement.WorldRef
    if not world then return false end
    local position = world.GetMapSpawn()
    if not position then return false end
    task.spawn(function()
        if StealthRef and StealthRef.GlideTo then
            StealthRef.GlideTo(position, { Speed = ConfigRef.Settings.GlideSpeed or 48 })
        else
            local _, root = getCharacterParts()
            if root then root.CFrame = CFrame.new(position) end
        end
        if Movement.OnNotify then pcall(Movement.OnNotify, "Телепорт на карту выполнен") end
    end)
    return true
end

function Movement.AboveMap()
    local world = Movement.WorldRef
    if not world then return false end
    local center = world.GetMapCenter()
    if not center then return false end
    local target = center + Vector3.new(0, 120, 0)
    task.spawn(function()
        local _, root = getCharacterParts()
        if not root then return end
        if StealthRef and StealthRef.GlideTo then
            StealthRef.GlideTo(target, { Speed = 90, Height = 0 })
        else
            root.CFrame = CFrame.new(target)
        end
        task.wait(0.4)
    end)
    return true
end

function Movement.ToPlayer(playerName)
    local target = nil
    for _, player in ipairs(Players:GetPlayers()) do
        if string.lower(player.Name) == string.lower(playerName or "") then target = player end
    end
    if not target or not target.Character then return false end
    local root = target.Character:FindFirstChild("HumanoidRootPart")
    if not root then return false end
    task.spawn(function()
        if StealthRef and StealthRef.GlideTo then
            StealthRef.GlideTo(root.Position, {})
        else
            local _, myRoot = getCharacterParts()
            if myRoot then myRoot.CFrame = root.CFrame * CFrame.new(0, 0, 3) end
        end
    end)
    return true
end

---------------------------------------------------------------------
-- Anti-AFK
---------------------------------------------------------------------

function Movement.SetAntiAFK(value)
    Movement.AntiAFKEnabled = value and true or false
    if value then
        local virtualUser = game:GetService("VirtualUser")
        antiAFKConnection = localPlayer.Idled:Connect(function()
            pcall(function()
                virtualUser:CaptureController()
                virtualUser:ClickButton2(Vector2.new())
            end)
            note("anti-afk pulse (idle)")
        end)
        connections[#connections + 1] = antiAFKConnection
        -- страховочный пульс каждые 60 секунд (не все экзекьюторы шлют Idled)
        task.spawn(function()
            while Movement.AntiAFKEnabled do
                task.wait(60)
                if not Movement.AntiAFKEnabled then break end
                pcall(function()
                    virtualUser:CaptureController()
                    virtualUser:ClickButton2(Vector2.new())
                end)
                note("anti-afk pulse (periodic)")
            end
        end)
    elseif antiAFKConnection then
        pcall(function() antiAFKConnection:Disconnect() end)
        antiAFKConnection = nil
    end
end

---------------------------------------------------------------------
-- Lifecycle
---------------------------------------------------------------------

function Movement.Configure(config, stealth)
    ConfigRef = config
    StealthRef = stealth
    Movement.Debug = config.Settings.DebugLogs == true

    -- Re-apply speed/jump on respawn.
    connections[#connections + 1] = localPlayer.CharacterAdded:Connect(function(character)
        local humanoid = character:WaitForChild("Humanoid", 5)
        if humanoid then
            task.wait(0.3)
            Movement.ApplySpeed(ConfigRef.Settings.WalkSpeed)
            Movement.ApplyJump(ConfigRef.Settings.JumpPower)
        end
    end)
    if localPlayer.Character then
        Movement.ApplySpeed(ConfigRef.Settings.WalkSpeed)
        Movement.ApplyJump(ConfigRef.Settings.JumpPower)
    end
end

function Movement.Destroy()
    noclipRunning = false
    infJumpRunning = false
    clickTPActive = false
    if clickTPConnection then
        pcall(function() clickTPConnection:Disconnect() end)
        clickTPConnection = nil
    end
    for _, connection in ipairs(connections) do
        pcall(function() connection:Disconnect() end)
    end
    connections = {}
    -- Full reset to vanilla values.
    local humanoid = getCharacterParts()
    if humanoid then
        pcall(function()
            humanoid.WalkSpeed = 16
            humanoid.JumpPower = 50
        end)
    end
end

return Movement
]====]

M["modules/visuals.lua"] = [====[
-- MilfaCheatHUB • Murder Mystery 2
-- Visuals: fullbright, no fog, corpse/barrier cleanup, FPS mode v0.1.0.
--
-- All client-side Lighting tweaks (zero server footprint):
--   * Fullbright: brightness 3, clock 14, ambient light gray, no color shift;
--   * NoFog: FogEnd 100000, FogStart 0, expose desaturated fog color;
--   * corpses: MM2 ragdolls are workspace children named "Raggy";
--   * barriers: Model "GlitchProof" (map edge walls) — removal is client-side
--     only and harmless to the server;
--   * FPS mode: kill particles/sparkles/shadows for weak phones.

local Lighting = game:GetService("Lighting")
local Workspace = game:GetService("Workspace")

local Visuals = {}

Visuals.Debug = false

local ConfigRef = nil
local connections = {}
local savedLighting = nil
local fullbrightOn = false
local noFogOn = false

local function note(...)
    if Visuals.Debug then print("[mh vis]", ...) end
end

local function snapshotLighting()
    if savedLighting then return end
    savedLighting = {
        Brightness = Lighting.Brightness,
        ClockTime = Lighting.ClockTime,
        Ambient = Lighting.Ambient,
        OutdoorAmbient = Lighting.OutdoorAmbient,
        GlobalShadows = Lighting.GlobalShadows,
        FogEnd = Lighting.FogEnd,
        FogStart = Lighting.FogStart,
        FogColor = Lighting.FogColor,
    }
end

function Visuals.SetFullbright(value)
    fullbrightOn = value and true or false
    if value then
        snapshotLighting()
        pcall(function()
            Lighting.Brightness = 3
            Lighting.ClockTime = 14
            Lighting.Ambient = Color3.fromRGB(178, 178, 178)
            Lighting.OutdoorAmbient = Color3.fromRGB(178, 178, 178)
            Lighting.GlobalShadows = false
        end)
    else
        if savedLighting then
            pcall(function()
                Lighting.Brightness = savedLighting.Brightness
                Lighting.ClockTime = savedLighting.ClockTime
                Lighting.Ambient = savedLighting.Ambient
                Lighting.OutdoorAmbient = savedLighting.OutdoorAmbient
                Lighting.GlobalShadows = savedLighting.GlobalShadows
            end)
        end
    end
end

function Visuals.SetNoFog(value)
    noFogOn = value and true or false
    if value then
        snapshotLighting()
        pcall(function()
            Lighting.FogEnd = 100000
            Lighting.FogStart = 0
        end)
    else
        if savedLighting then
            pcall(function()
                Lighting.FogEnd = savedLighting.FogEnd
                Lighting.FogStart = savedLighting.FogStart
                Lighting.FogColor = savedLighting.FogColor
            end)
        end
    end
end

---------------------------------------------------------------------
-- Corpse & barrier cleanup
---------------------------------------------------------------------

local function sweepNamed(parent, name)
    local count = 0
    pcall(function()
        for _, child in ipairs(parent:GetChildren()) do
            if child.Name == name then
                child:Destroy()
                count = count + 1
            end
        end
    end)
    return count
end

function Visuals.SetRemoveRagdolls(value)
    ConfigRef.Settings.RemoveRagdolls = value and true or false
    if value then
        sweepNamed(Workspace, "Raggy")
        connections[#connections + 1] = Workspace.ChildAdded:Connect(function(child)
            if ConfigRef.Settings.RemoveRagdolls and child.Name == "Raggy" then
                task.wait(0.5)
                pcall(function() child:Destroy() end)
            end
        end)
    else
        for _, connection in ipairs(connections) do connection:Disconnect() end
        connections = {}
    end
end

function Visuals.SetRemoveBarriers(value)
    ConfigRef.Settings.RemoveBarriers = value and true or false
    if value then
        pcall(function()
            for _, descendant in ipairs(Workspace:GetDescendants()) do
                if descendant.Name == "GlitchProof" then
                    descendant:Destroy()
                end
            end
        end)
        note("barriers removed")
    end
end

---------------------------------------------------------------------
-- FPS mode
---------------------------------------------------------------------

function Visuals.SetFpsMode(value)
    pcall(function()
        if value then
            Lighting.GlobalShadows = false
            Lighting.FogEnd = 950
            settings().Rendering.QualityLevel = Enum.QualityLevel.Level01
        else
            if savedLighting then
                Lighting.GlobalShadows = savedLighting.GlobalShadows
                Lighting.FogEnd = savedLighting.FogEnd
            end
            settings().Rendering.QualityLevel = Enum.QualityLevel.Automatic
        end
    end)
end

---------------------------------------------------------------------
-- Lifecycle
---------------------------------------------------------------------

function Visuals.Configure(config)
    ConfigRef = config
    Visuals.Debug = config.Settings.DebugLogs == true
end

function Visuals.Destroy()
    for _, connection in ipairs(connections) do
        pcall(function() connection:Disconnect() end)
    end
    connections = {}
    Visuals.SetFullbright(false)
    Visuals.SetNoFog(false)
    Visuals.SetFpsMode(false)
end

return Visuals
]====]

M["modules/troll.lua"] = [====[
-- MilfaCheatHUB • Murder Mystery 2
-- Troll pack v0.3.1 (FIXED against live scripts).
--
-- Починено/добавлено:
--   * Эмоции: ремоут это Remotes.PlayEmote (сразу под Remotes, рекурсивный
--     поиск — подтверждено W-Azeox). Пробуем :FireServer(имя) и :Fire(имя).
--     Если ремоута нет — локальная анимация (видно только тебе).
--   * Фейк-пистолет: Remotes.Gameplay.FakeGun:FireServer(true) — родной
--     предмет игры, видно ВСЕМ (подтверждено 3 скриптами).
--   * Фейк нож: метод «как делают другие» (MM2 Mods): игрушка SprayPaint
--     (Remotes.Extras.ReplicateToy) рисует ДЕКАЛЬ ножа на правой руке —
--     спрей реплицируется сервером, ВСЕ видят нож в твоей руке.
--   * Фейк глитч: персонаж «глючит» для всех — микроТП, спины, дёрганья
--     анимаций (CFrame реплицируется, другие игроки это видят).
--   * Невидимка: Remotes.Gameplay.Stealth:FireServer(true) — родная
--     невидимость игры (подтверждено 3 скриптами), risky.
--   * Фейк смерть 2 типа остались (рагдолл/призрак, локальный вид).

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local SoundService = game:GetService("SoundService")
local RunService = game:GetService("RunService")

local Troll = {}

Troll.ActiveKind = nil      -- "Рагдолл" | "Призрак" | nil
Troll.FakeGlitch = false
Troll.Invisible = false
Troll.Debug = false

local ConfigRef = nil
local StealthRef = nil
local localPlayer = Players.LocalPlayer

local savedState = nil
local ghostParts = {}
local connections = {}
local deathSound = nil

-- Фейк глитч state
local glitchConnection = nil
-- Фейк нож state
local fakeKnifeDecals = {}

local function note(...)
    if Troll.Debug then print("[mh troll]", ...) end
end

local function findRemote(name, className)
    local found
    pcall(function() found = ReplicatedStorage:FindFirstChild(name, true) end)
    if found and (not className or found:IsA(className)) then return found end
    return nil
end

local function playOof()
    pcall(function()
        if not deathSound then
            deathSound = Instance.new("Sound")
            deathSound.SoundId = "rbxasset://sounds/uuhhh.mp3"
            deathSound.Volume = 0.7
            deathSound.Parent = SoundService
        end
        deathSound:Play()
    end)
end

local function getCharacterParts()
    local character = localPlayer and localPlayer.Character
    if not character then return nil, nil, nil end
    return character, character:FindFirstChildOfClass("Humanoid"), character:FindFirstChild("HumanoidRootPart")
end

---------------------------------------------------------------------
-- Fake death type 1: ragdoll
---------------------------------------------------------------------

local function enterRagdoll()
    local character, humanoid, root = getCharacterParts()
    if not humanoid or not root then return false end
    savedState = {
        WalkSpeed = humanoid.WalkSpeed,
        JumpPower = humanoid.JumpPower,
        PlatformStand = humanoid.PlatformStand,
        AutoRotate = humanoid.AutoRotate,
    }
    pcall(function()
        humanoid.AutoRotate = false
        humanoid.PlatformStand = true
        humanoid.WalkSpeed = 0
        root.CFrame = root.CFrame * CFrame.Angles(0, 0, math.rad(82))
    end)
    playOof()
    return true
end

---------------------------------------------------------------------
-- Fake death type 2: ghost
---------------------------------------------------------------------

local function enterGhost()
    local character = localPlayer and localPlayer.Character
    if not character then return false end
    ghostParts = {}
    pcall(function()
        for _, descendant in ipairs(character:GetDescendants()) do
            if descendant:IsA("BasePart") then
                ghostParts[descendant] = descendant.Transparency
                descendant.Transparency = 1
                descendant.LocalTransparencyModifier = 1
            elseif descendant:IsA("Decal") then
                ghostParts[descendant] = descendant.Transparency
                descendant.Transparency = 1
            end
        end
    end)
    playOof()
    return true
end

local function restoreRagdoll()
    local character, humanoid, root = getCharacterParts()
    if humanoid and savedState then
        pcall(function()
            humanoid.PlatformStand = savedState.PlatformStand
            humanoid.AutoRotate = savedState.AutoRotate
            humanoid.WalkSpeed = savedState.WalkSpeed
            humanoid.JumpPower = savedState.JumpPower
        end)
    end
    if root and root.Parent then
        pcall(function()
            local pos = root.Position
            root.CFrame = CFrame.new(pos + Vector3.new(0, 3, 0))
            humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)
        end)
    end
    savedState = nil
end

local function restoreGhost()
    for descendant, transparency in pairs(ghostParts) do
        pcall(function()
            if descendant.Parent then
                descendant.Transparency = transparency
                if descendant:IsA("BasePart") then
                    descendant.LocalTransparencyModifier = 0
                end
            end
        end)
    end
    ghostParts = {}
end

-- kind: nil (выключить) | "Рагдолл" | "Призрак"
function Troll.SetFakeDeath(kind)
    if kind == Troll.ActiveKind then return true end
    if Troll.ActiveKind == "Рагдолл" then restoreRagdoll() end
    if Troll.ActiveKind == "Призрак" then restoreGhost() end
    Troll.ActiveKind = nil
    if kind == "Рагдолл" then
        if enterRagdoll() then Troll.ActiveKind = kind end
    elseif kind == "Призрак" then
        if enterGhost() then Troll.ActiveKind = kind end
    end
    return true
end

function Troll.CycleFakeDeath()
    if Troll.ActiveKind == nil then
        Troll.SetFakeDeath("Рагдолл")
        return "фейк-смерть: РАГДОЛЛ"
    elseif Troll.ActiveKind == "Рагдолл" then
        Troll.SetFakeDeath("Призрак")
        return "фейк-смерть: ПРИЗРАК"
    else
        Troll.SetFakeDeath(nil)
        return "фейк-смерть выключена"
    end
end

---------------------------------------------------------------------
-- Эмоции: Remotes.PlayEmote (рекурсивно) + локальный фолбэк
---------------------------------------------------------------------

local EMOTE_ANIMS = {
    ["Махать"] = "rbxassetid://507770239",
    ["Танец"] = "rbxassetid://507771013",
    ["Радость"] = "rbxassetid://507770677",
    ["Смех"] = "rbxassetid://507770819",
    ["Указать"] = "rbxassetid://507770453",
    ["Танец 2"] = "rbxassetid://507771955",
    ["Танец 3"] = "rbxassetid://507777268",
    ["Zen"] = "rbxassetid://507771955",
}

-- имена для игрового ремоута (список живых эмотов: xsync69/fogyhub —
-- sit, zombie, ninja, zen, floss, dab + wave/dance/cheer/laugh/point)
local GAME_EMOTE_NAMES = {
    ["Zen"] = "zen",
    ["Махать"] = "wave",
    ["Танец"] = "dance",
    ["Радость"] = "cheer",
    ["Смех"] = "laugh",
    ["Указать"] = "point",
    ["Сесть"] = "sit",
    ["Зомби"] = "zombie",
    ["Ниндзя"] = "ninja",
    ["Флосс"] = "floss",
    ["Дэб"] = "dab",
}

local emoteTrack = nil

function Troll.PlayEmote(buttonName)
    local character, humanoid = getCharacterParts()
    if not humanoid then return false, "нет персонажа" end
    if buttonName == "Сесть" then
        pcall(function() humanoid.Sit = true end)
        return true, "сел"
    end
    -- 1) родной игровой ремоут (видно всем)
    local played = false
    pcall(function()
        local playEmote = findRemote("PlayEmote", "RemoteEvent")
        local gameName = GAME_EMOTE_NAMES[buttonName]
        if playEmote and gameName then
            local fired = false
            pcall(function() playEmote:FireServer(gameName); fired = true end)
            if not fired then pcall(function() playEmote:Fire(gameName); fired = true end) end
            played = fired
        end
    end)
    if played then
        return true, "эмоция: " .. buttonName
    end
    -- 2) локальная анимация (видно только тебе)
    local animator = humanoid:FindFirstChildOfClass("Animator")
    if not animator then return false, "нет Animator" end
    local animId = EMOTE_ANIMS[buttonName]
    if not animId then return false, "неизвестная эмоция" end
    pcall(function()
        if emoteTrack then emoteTrack:Stop(0.2) end
        local animation = Instance.new("Animation")
        animation.AnimationId = animId
        emoteTrack = animator:LoadAnimation(animation)
        emoteTrack:Play()
    end)
    return true, "локальная эмоция: " .. buttonName
end

---------------------------------------------------------------------
-- SprayPaint-игрушка: база для фейка ножа (видно всем)
---------------------------------------------------------------------

local KNIFE_SPRAY_IDS = { 15093138669, 15096522641 }

-- Достаём SprayPaint в Character (сначала ReplicateToy, потом свой).
local function obtainSprayPaint()
    local backpack = localPlayer:FindFirstChildOfClass("Backpack")
    local character = localPlayer.Character
    local spray = character and character:FindFirstChild("SprayPaint")
    if spray then return spray end
    -- из "Toys" папки или напрямую
    local toys = backpack and (backpack:FindFirstChild("Toys") or backpack)
    spray = toys and toys:FindFirstChild("SprayPaint")
    if not spray then
        pcall(function()
            local replicateToy = findRemote("ReplicateToy", "RemoteFunction")
            if replicateToy then replicateToy:InvokeServer("SprayPaint") end
        end)
        task.wait(0.4)
        toys = backpack and (backpack:FindFirstChild("Toys") or backpack)
        spray = toys and toys:FindFirstChild("SprayPaint")
    end
    if spray and character then
        local humanoid = character:FindFirstChildOfClass("Humanoid")
        if humanoid then pcall(function() humanoid:EquipTool(spray) end) end
        spray = character:FindFirstChild("SprayPaint")
    end
    return spray
end

-- Спрей картинки на часть. Видно всем (реплицируется сервером).
local function sprayOn(spray, imageId, normalId, size, part, cframe)
    local ok = false
    pcall(function()
        local remote = spray:FindFirstChild("Remote")
        if remote and remote:IsA("RemoteEvent") then
            remote:FireServer(imageId, normalId, size, part, cframe)
            ok = true
        end
    end)
    return ok
end

-- Фейк-нож (метод MM2 Mods «Fake Knife»): ДВА спрея на правую руку —
--   15093138669 на NormalId.Right и 15096522641 на NormalId.Left (в оригинале
--   именно так: разные грани, один size 3). Туl переносится в Character
--   ПРЯМЫМ parent (EquipTool у игрушек может сработать не на всех экзекьюторах)
--   и возвращается в рюкзак после выстрела ремоутом.
function Troll.FakeKnife()
    local character, _, root = getCharacterParts()
    if not character or not root then return false, "нет персонажа" end
    local hand = character:FindFirstChild("RightHand") or character:FindFirstChild("Right Arm")
    if not hand then return false, "нет руки" end
    local spray = obtainSprayPaint()
    if not spray then return false, "SprayPaint недоступна" end
    -- прямой перенос в Character (как в оригинале) + фолбэк EquipTool
    if spray.Parent ~= character then
        local moved = pcall(function() spray.Parent = character end)
        if not moved or spray.Parent ~= character then
            local humanoid = character:FindFirstChildOfClass("Humanoid")
            if humanoid then pcall(function() humanoid:EquipTool(spray) end) end
        end
    end
    if spray.Parent ~= character then return false, "спрей не удалось взять в руку" end
    local sprayRemote = spray:FindFirstChild("Remote")
    local okCount = 0
    if sprayRemote and sprayRemote:IsA("RemoteEvent") then
        local cframe = hand.CFrame * CFrame.new(0, 0, -0.7)
        if sprayOn(spray, KNIFE_SPRAY_IDS[1], Enum.NormalId.Right, 3, hand, cframe) then
            okCount = okCount + 1
        end
        if sprayOn(spray, KNIFE_SPRAY_IDS[2], Enum.NormalId.Left, 3, hand, cframe) then
            okCount = okCount + 1
        end
    end
    -- вернуть спрей в рюкзак (не мешает играть)
    pcall(function()
        local backpack = localPlayer:FindFirstChildOfClass("Backpack")
        if backpack then spray.Parent = backpack end
    end)
    if okCount > 0 then
        return true, "фейк-нож на руке (видно всем)"
    end
    return false, "спрей не сработал"
end

---------------------------------------------------------------------
-- Фейк-бомба: локальная игрушка (для скринов/видео)
---------------------------------------------------------------------

local fakeBombModel = nil

function Troll.FakeBomb()
    local character, _, root = getCharacterParts()
    if not root then return false, "нет персонажа" end
    pcall(function()
        if fakeBombModel then fakeBombModel:Destroy(); fakeBombModel = nil end
        local bomb = Instance.new("Part")
        bomb.Size = Vector3.new(1, 1.2, 1)
        bomb.Shape = Enum.PartType.Ball
        bomb.Color = Color3.fromRGB(20, 20, 24)
        bomb.Material = Enum.Material.SmoothPlastic
        bomb.CanCollide = false
        bomb.Massless = true
        bomb.CFrame = root.CFrame * CFrame.new(0, -2.6, -1.6)
        local light = Instance.new("PointLight")
        light.Color = Color3.fromRGB(255, 60, 40)
        light.Range = 6
        light.Brightness = 2
        light.Parent = bomb
        local spark = Instance.new("ParticleEmitter")
        spark.Color = ColorSequence.new(Color3.fromRGB(255, 180, 60))
        spark.Size = NumberSequence.new(0.25, 0)
        spark.Lifetime = NumberRange.new(0.2, 0.4)
        spark.Rate = 40
        spark.Speed = NumberRange.new(1, 2)
        spark.Parent = bomb
        local weld = Instance.new("WeldConstraint")
        weld.Part0 = bomb
        weld.Part1 = root
        weld.Parent = bomb
        bomb.Parent = character
        fakeBombModel = bomb
        task.delay(6, function()
            pcall(function()
                if fakeBombModel == bomb then bomb:Destroy(); fakeBombModel = nil end
            end)
        end)
    end)
    playOof()
    return true, "фейк-бомба у ног (6 сек, видно на твоём экране)"
end

---------------------------------------------------------------------
-- Фейк-пистолет: родной предмет игры (видно всем)
---------------------------------------------------------------------

function Troll.FakeGun()
    local ok = pcall(function()
        local fakeGun = findRemote("FakeGun", "RemoteEvent")
        if fakeGun then
            fakeGun:FireServer(true)
        else
            error("не найден")
        end
    end)
    if ok then return true, "фейк-пистолет показан (видно всем)" end
    return false, "ремоут FakeGun не найден"
end

---------------------------------------------------------------------
-- Невидимка: родной Stealth игры (видно всем)
---------------------------------------------------------------------

function Troll.SetInvisible(value)
    Troll.Invisible = value and true or false
    ConfigRef.Settings.Invisible = Troll.Invisible
    local ok = pcall(function()
        local stealthRemote = findRemote("Stealth", "RemoteEvent")
        if not stealthRemote then error("нет") end
        stealthRemote:FireServer(Troll.Invisible)
    end)
    if ok then
        return true, Troll.Invisible and "невидимка ВКЛ (родная стелс-функция)" or "невидимка ВЫКЛ"
    end
    return false, "ремоут Stealth не найден"
end

---------------------------------------------------------------------
-- Спид-глитч (то, что в популярных хабах зовут Glitch / Slide Glitch):
-- CFrame-сдвиг по направлению бега каждый Heartbeat (fogyhub: force 45,
-- CGS: velocity*1.48). Персонаж визуально «глится» — сдвиг реплицируется.
-- ВАЖНО: работает ТОЛЬКО когда персонаж реально бежит (MoveDirection > 0).
---------------------------------------------------------------------

function Troll.SetFakeGlitch(value)
    Troll.FakeGlitch = value and true or false
    ConfigRef.Settings.FakeGlitch = Troll.FakeGlitch
    if glitchConnection then
        pcall(function() glitchConnection:Disconnect() end)
        glitchConnection = nil
    end
    if not value then
        return true, "спид-глитч ВЫКЛ"
    end
    glitchConnection = RunService.Heartbeat:Connect(function(deltaTime)
        if not Troll.FakeGlitch then return end
        pcall(function()
            local character = localPlayer.Character
            local humanoid = character and character:FindFirstChildOfClass("Humanoid")
            local root = character and character:FindFirstChild("HumanoidRootPart")
            if root and humanoid and humanoid.Health > 0 and humanoid.MoveDirection.Magnitude > 0 then
                local force = ConfigRef.Settings.GlitchForce or 40
                local slide = Vector3.new(humanoid.MoveDirection.X, 0, humanoid.MoveDirection.Z).Unit
                root.CFrame = root.CFrame + (slide * (force * deltaTime))
            end
        end)
    end)
    return true, "спид-глитч ВКЛ (глитч-бег, видно всем)"
end

---------------------------------------------------------------------
-- Спид-глитч (см. SetFakeGlitch): отключение в Shutdown и при выгрузке
---------------------------------------------------------------------

function Troll.Configure(config, stealth)
    ConfigRef = config
    StealthRef = stealth
    Troll.Debug = config.Settings.DebugLogs == true
    connections[#connections + 1] = localPlayer.CharacterAdded:Connect(function()
        if Troll.ActiveKind then
            Troll.ActiveKind = nil
            savedState = nil
            ghostParts = {}
            fakeBombModel = nil
            note("fake death cleared by respawn")
        end
    end)
end

function Troll.Shutdown()
    pcall(function() Troll.SetFakeDeath(nil) end)
    Troll.ActiveKind = nil
    if Troll.FakeGlitch then pcall(function() Troll.SetFakeGlitch(false) end) end
    if emoteTrack then pcall(function() emoteTrack:Stop(0.1) end) emoteTrack = nil end
    if deathSound then pcall(function() deathSound:Destroy() end) deathSound = nil end
    pcall(function() if fakeBombModel then fakeBombModel:Destroy(); fakeBombModel = nil end end)
    pcall(function() if fakeKnifeDecals then for _, d in ipairs(fakeKnifeDecals) do d:Destroy() end end end)
    for _, connection in ipairs(connections) do
        pcall(function() connection:Disconnect() end)
    end
    connections = {}
end

return Troll
]====]

M["modules/beta.lua"] = [====[
-- MilfaCheatHUB • Murder Mystery 2
-- BETA: round outcome prediction v0.2.0.
--
-- Honest heuristic (no magic): MM2 gives us roles, alive flags and positions.
-- The estimate weighs the factors that actually decide public rounds:
--   * is the sheriff/hero still alive (biggest single factor);
--   * murderer <-> sheriff distance (far = sheriff can safely snipe,
--     point blank = murderer usually stabs first);
--   * number of alive innocents (extra shields/time for the murderer to burn);
--   * timer pressure (under 20s a murderer cannot clear the map);
--   * whether YOU are the sheriff/hero (your skill changes the odds).
-- Output: probability split for the LAW side (sheriff/innocents surviving)
-- vs the MURDERER, plus the factor breakdown so the user sees the "why".

local Players = game:GetService("Players")

local Beta = {}

Beta.Debug = false
Beta.Last = nil   -- последний расчёт {Sheriff, Murderer, Text, Factors}

local ConfigRef = nil
local RolesRef = nil
local WorldRef = nil
local localPlayer = Players.LocalPlayer

local function note(...)
    if Beta.Debug then print("[mh beta]", ...) end
end

local function rootOf(playerName)
    local player = Players:FindFirstChild(playerName)
    local character = player and player.Character
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    local root = character and character:FindFirstChild("HumanoidRootPart")
    if humanoid and humanoid.Health > 0 and root then return root end
    return nil
end

local function myRoot()
    local character = localPlayer and localPlayer.Character
    return character and character:FindFirstChild("HumanoidRootPart") or nil
end

---------------------------------------------------------------------
-- Core computation
---------------------------------------------------------------------

-- Возвращает: {Sheriff = 0..100, Murderer = 0..100, Text = "...", Factors = {...}, Ready = bool}
function Beta.Compute()
    local murdererNames = RolesRef.FindByRole("Murderer")
    local sheriffNames = RolesRef.FindByRole("Sheriff")
    local heroNames = RolesRef.FindByRole("Hero")

    if #murdererNames == 0 then
        Beta.Last = {
            Ready = false,
            Sheriff = 50,
            Murderer = 50,
            Text = "маньяк неизвестен — обнови роли",
            Factors = {},
        }
        return Beta.Last
    end

    local lawAlive = #sheriffNames + #heroNames
    local innocentsAlive = 0
    for name, role in pairs(RolesRef.Cache) do
        if RolesRef.IsAlive(name) and (role == "Innocent" or role == "Unknown") then
            if Players:FindFirstChild(name) then
                innocentsAlive = innocentsAlive + 1
            end
        end
    end

    local murdererRoot = rootOf(murdererNames[1])
    local lawRoot = nil
    for _, name in ipairs(sheriffNames) do
        lawRoot = lawRoot or rootOf(name)
    end
    for _, name in ipairs(heroNames) do
        lawRoot = lawRoot or rootOf(name)
    end

    local factors = {}
    local score = 50  -- вероятность победы стороны ЗАКОНА (шериф/выжившие)

    local timer = nil
    pcall(function() timer = WorldRef.GetTimer() end)

    if lawAlive == 0 then
        -- шерифа нет: мирные спасаются только таймером
        score = 28
        factors[#factors + 1] = "шериф/герой мёртв — исход решает таймер"
        if timer and timer <= 20 then
            score = score + 34
            factors[#factors + 1] = "меньше 20 сек — маньяк не успеет перебить всех"
        else
            score = score - math.min(10, innocentsAlive)
            factors[#factors + 1] = "времени много, мирных мало (" .. tostring(innocentsAlive) .. ")"
        end
    else
        -- дистанция маньяк <-> закон
        if murdererRoot and lawRoot then
            local distMS = (murdererRoot.Position - lawRoot.Position).Magnitude
            if distMS > 60 then
                score = score + 16
                factors[#factors + 1] = string.format("шериф далеко от маньяка (%.0fм) — безопасная позиция", distMS)
            elseif distMS < 18 then
                score = score - 14
                factors[#factors + 1] = string.format("маньяк вплотную к шерифу (%.0fм) — нож быстрее пистолета", distMS)
            else
                score = score + 4
                factors[#factors + 1] = string.format("средняя дистанция маньяк/шериф (%.0fм)", distMS)
            end
        else
            score = score - 6
            factors[#factors + 1] = "позиции неизвестны (не видно персонажей)"
        end
        -- давление на мирных
        if murdererRoot and myRoot() then
            local closest = math.huge
            for _, name in ipairs(RolesRef.FindByRole("Innocent")) do
                local root = rootOf(name)
                if root then
                    local d = (root.Position - murdererRoot.Position).Magnitude
                    if d < closest then closest = d end
                end
            end
            if closest ~= math.huge and closest < 25 then
                score = score - 5
                factors[#factors + 1] = string.format("маньяк уже прижал мирных (%.0fм до ближайшего)", closest)
            end
        end
        -- мирные = запас времени
        if innocentsAlive > 0 then
            local bonus = math.min(12, innocentsAlive * 3)
            score = score + bonus
            factors[#factors + 1] = "живых мирных: " .. tostring(innocentsAlive) .. " — маньяку нужно время"
        end
        -- ты сам
        if RolesRef.LocalIsSheriff() then
            score = score + 9
            factors[#factors + 1] = "ты шериф/герой — исход частично в твоих руках"
        elseif RolesRef.LocalIsMurderer() then
            score = score - 9
            factors[#factors + 1] = "ты маньяк — действуй, и прогноз изменится"
        end
        -- таймер
        if timer and timer <= 20 then
            score = score + 8
            factors[#factors + 1] = "меньше 20 сек — маньяку некогда"
        end
    end

    if score > 100 then score = 100 end
    if score < 0 then score = 0 end

    local lawRounded = math.floor(score + 0.5)
    local verdict
    if lawRounded >= 70 then
        verdict = "склоняется к ШЕРИФУ/мирным"
    elseif lawRounded <= 30 then
        verdict = "склоняется к МАНЬЯКУ"
    else
        verdict = "шансы примерно равны"
    end

    Beta.Last = {
        Ready = true,
        Sheriff = lawRounded,
        Murderer = 100 - lawRounded,
        Text = string.format("шериф/мирные %d%% • маньяк %d%% — %s", lawRounded, 100 - lawRounded, verdict),
        Factors = factors,
    }
    note("prediction: " .. Beta.Last.Text)
    return Beta.Last
end

function Beta.Summary()
    local result = Beta.Last or Beta.Compute()
    return result.Text
end

function Beta.Configure(config, roles, world)
    ConfigRef = config
    RolesRef = roles
    WorldRef = world
    Beta.Debug = config.Settings.DebugLogs == true
end

return Beta
]====]

M["modules/features.lua"] = [====[
-- MilfaCheatHUB • Murder Mystery 2
-- Feature wiring v0.4.0. GUI почищен (аудит NEX + разметка юзера):
-- 6 вкладок: ИГРОКИ / БОЙ / АВТО / ПЕРСОНАЖ / ТРОЛЛИНГ / СИСТЕМА.
-- Убрано: дубль-тоглы SheriffAim/MurderAim (кнопки делают то же),
-- слайдеры AimMaxDistance/AuraDelay/DodgeRadius/DodgeCooldown/FarmDelay/
-- PistolSpeed/PistolReturnDelay/EspMaxDistance (адекватные дефолты вшиты),
-- FakeBomb (видно только себе), RemoveRagdolls/RemoveBarriers (балласт),
-- NetworkStatus/mount-инфо, HumanizeDelays/GlideSpeed (внутренние).
-- AutoDodge: 1 слайдер профиля (Осторожно/Баланс/Агрессивно) вместо 4.
-- Эмоции: dropdown вместо 6 кнопок. ТП: dropdown вместо 3 кнопок.
-- Прогноз победы остаётся живым полем в ИГРОКАХ (ТЗ юзера).
-- Mobile: всё тапами; PC: горячие клавиши G/H/J/K.

local Players = game:GetService("Players")
local UserInputService = game:GetService("UserInputService")
local TeleportService = game:GetService("TeleportService")
local localPlayer = Players.LocalPlayer

local Features = {}
Features.__index = Features

-- профили AutoDodge: [радиус, сила, кулдаун]
local DODGE_PROFILES = {
    { Radius = 60, Power = 10, Cooldown = 2.0, Name = "Осторожно" },
    { Radius = 45, Power = 12, Cooldown = 1.2, Name = "Баланс" },
    { Radius = 30, Power = 16, Cooldown = 0.7, Name = "Агрессивно" },
}

function Features.new(config, ui, roles, network, world, esp, farm, combat, movement, visuals, alive, stealth, troll, beta)
    local self = setmetatable({}, Features)
    self.Config = config
    self.UI = ui
    self.Roles = roles
    self.Network = network
    self.World = world
    self.ESP = esp
    self.Farm = farm
    self.Combat = combat
    self.Movement = movement
    self.Visuals = visuals
    self.Alive = alive
    self.Stealth = stealth
    self.Troll = troll
    self.Beta = beta
    self.Running = false
    self.LastGrabAt = 0
    self.Connections = {}
    self.LastPredictionAt = 0
    return self
end

function Features:Build()
    local colors = self.Config.Colors
    local settings = self.Config.Settings

    local playersTab = self.UI:CreateTab("Игроки", "ESP", colors.ESP)
    local combatTab = self.UI:CreateTab("Бой", "HIT", colors.Combat)
    local autoTab = self.UI:CreateTab("Авто", "BOT", colors.Combat)
    local playerTab = self.UI:CreateTab("Персонаж", "PLR", colors.Player)
    local trollTab = self.UI:CreateTab("Троллинг", "TRL", colors.Misc)
    local systemTab = self.UI:CreateTab("Система", "SYS", colors.Misc)

    -- ============================== ИГРОКИ ==============================
    self.UI:AddHeading(playersTab, "Кто есть кто (видно до ножа)")
    self.RoleStatus = self.UI:AddText(playersTab, "Роли", "обновляется автоматически")
    self.ESP.OnAlert = function(message)
        pcall(function() self.RoleStatus:Set(message) end)
    end
